	// mdGetDesc: hover tooltip asked for a spell's auto-generated description.
	void OnJsMagicGetDesc(const char* data)
	{
		if (!data)
			return;
		const auto j = json::parse(data, nullptr, false);
		if (j.is_discarded() || !j.is_object())
			return;
		const auto plugin = j.value("plugin", std::string(""));
		const auto localId = j.value("localId", 0u);
		const auto formId = j.value("formId", 0u);
		SKSE::GetTaskInterface()->AddTask([plugin, localId, formId]() {
			PushToMagicView("mdDesc", SpellActions::DescriptionJson(plugin, localId, formId));
		});
	}

	// mdIconList: the icon picker's Refresh — re-scan icons/custom/ right now.
	void OnJsMagicIconList(const char*)
	{
		SKSE::GetTaskInterface()->AddTask([]() {
			PushToMagicView("mdIcons", CustomIconsJson());
		});
	}

	// ------------------------------------------- magic config: id reconcile
	/* Runtime FormIDs are NOT durable, and the Spell Deck's config stores them
	 * beside the durable (plugin, localId) pair. On 2026-08-18 Rober's
	 * "Dragonknight" (KittyClass_Dragonknight.esp|0x88C) moved from mod index
	 * 0x81 to 0x80 — the plugin stopped counting as a full plugin — and every
	 * stored 0x81xxxxxx id in magic went stale in one launch. The visible
	 * damage: ten entries "with no engine metadata" (the view's enrich pass
	 * keys off the id), and a re-added Dragonknight sitting as a SECOND entry
	 * with icon:"" in front of the original that still held
	 * icons/custom/Dragonknight-2.png.
	 *
	 * So: re-resolve every stored id from its durable pair, then merge the
	 * duplicates that the stale ids allowed to be created.
	 *
	 * ⛔ kPostLoadGame ONLY — with no save loaded LookupForm answers nothing and
	 * this would "repair" a config into zeroes. Runs on the main thread (SKSE
	 * message dispatch). Marker: "magic id repair:".
	 *
	 * Local ids are stored file-width-masked already (KnownSpellsJson builds
	 * them through ActorIdentity::LocalIdOf, which masks — never CommonLib's
	 * GetLocalFormID()), so they are handed to LookupForm as-is: that is the
	 * ESL-safe lookup. */
	std::string MagicIdKey(const std::string& plugin, std::uint32_t localId)
	{
		if (plugin.empty() || !localId)
			return {};
		std::string k = plugin;
		std::transform(k.begin(), k.end(), k.begin(),
			[](unsigned char c) { return static_cast<char>(std::tolower(c)); });
		char hex[16];
		std::snprintf(hex, sizeof(hex), "|%x", localId);
		k += hex;
		return k;
	}

	// The live runtime id for a durable pair, or 0 when it cannot be resolved
	// (plugin no longer in the load order, no save loaded, record removed).
	std::uint32_t MagicLiveFormId(const std::string& plugin, std::uint32_t localId)
	{
		if (plugin.empty() || !localId)
			return 0;
		auto* dh = RE::TESDataHandler::GetSingleton();
		if (!dh)
			return 0;
		auto* form = dh->LookupForm(localId, plugin);
		return form ? form->GetFormID() : 0;
	}

	// Fill dst's blank metadata from src. Never overwrites a non-empty field —
	// the survivor's own choices (and the player's) always win.
	void MagicFillBlanks(SpellEntry& dst, const SpellEntry& src)
	{
		auto take = [](std::string& d, const std::string& s) {
			if (d.empty() && !s.empty())
				d = s;
		};
		take(dst.icon, src.icon);
		take(dst.name, src.name);
		take(dst.slot, src.slot);
		take(dst.school, src.school);
		take(dst.element, src.element);
		take(dst.archetype, src.archetype);
		take(dst.tier, src.tier);
		take(dst.category, src.category);
		// A "voice" slot is real information a blank can't express: an entry
		// that knows it is a shout/power must not be flattened to a hand spell.
		if (dst.slot != "voice" && src.slot == "voice")
			dst.slot = "voice";
	}

	// Returns a one-line summary of what was repaired, or "" when nothing was.
	// Caller persists (outside the config lock).
	std::string MagicReconcileIds()
	{
		int idFixed = 0, merged = 0, metaFixed = 0, unresolved = 0;
		std::vector<std::string> mergedNames;
		{
			std::lock_guard l(g_configMutex);

			// --- pass 1: re-resolve every stored runtime id from its pair ----
			auto fixEntryId = [&](const std::string& plugin, std::uint32_t localId,
								  std::uint32_t& formId, int& counter) {
				if (plugin.empty() || !localId)
					return;
				const auto live = MagicLiveFormId(plugin, localId);
				if (!live) {
					++unresolved;
					return;
				}
				if (live != formId) {
					formId = live;
					++counter;
				}
			};
			for (auto& s : g_magicConfig.spells)
				fixEntryId(s.plugin, s.localId, s.formId, idFixed);
			for (auto& m : g_magicConfig.removed)
				fixEntryId(m.plugin, m.localId, m.formId, metaFixed);
			for (auto& c : g_magicConfig.combos)
				for (auto& m : c.spells)
					fixEntryId(m.plugin, m.localId, m.formId, metaFixed);

			/* --- pass 2: merge duplicates ------------------------------------
			 * Keyed (plugin, localId, CATEGORY) — deliberately NOT the pair
			 * alone. The same spell in two different categories is a SUPPORTED
			 * configuration, not a bug: the add-picker's "already added" check
			 * is scoped to the target category (knownRow's inCat) and
			 * newSpellId() mints "0x…-2" precisely so a second copy can exist.
			 * Merging on the pair alone would silently delete a rail the player
			 * built on purpose. Two rows of one spell in ONE category is the
			 * shape that only ever appears by accident — that is the one the
			 * stale ids created, and the only one dropped here.
			 *
			 * FIRST occurrence survives: it is the older entry, the one
			 * carrying the icon and the mode the player set. A later duplicate
			 * only ever contributes what the survivor lacks. */
			std::unordered_map<std::string, std::size_t> firstAt;
			std::vector<SpellEntry>                      keep;
			std::unordered_map<std::string, std::string> idRemap;  // dropped entry id -> survivor id
			keep.reserve(g_magicConfig.spells.size());
			for (auto& s : g_magicConfig.spells) {
				const auto pairKey = MagicIdKey(s.plugin, s.localId);
				const auto key = pairKey.empty() ? std::string() : (pairKey + "#" + s.category);
				if (key.empty()) {   // no durable identity — never merged
					keep.push_back(std::move(s));
					continue;
				}
				const auto it = firstAt.find(key);
				if (it == firstAt.end()) {
					firstAt.emplace(key, keep.size());
					keep.push_back(std::move(s));
					continue;
				}
				SpellEntry& survivor = keep[it->second];
				MagicFillBlanks(survivor, s);
				if (!s.id.empty() && s.id != survivor.id)
					idRemap.emplace(s.id, survivor.id);
				mergedNames.push_back(survivor.name.empty() ? survivor.id : survivor.name);
				++merged;
			}
			// ALWAYS written back: every element above was moved OUT of the
			// original vector, so leaving it in place on the no-duplicate path
			// would hand the deck a list of blanked entries.
			g_magicConfig.spells = std::move(keep);

			/* --- pass 2b: the art rescue across categories --------------------
			 * The same spell filed under two categories is legal (above), so the
			 * copy the player just re-added under a DIFFERENT rail keeps its own
			 * row — but it must not sit there iconless while its sibling holds
			 * the art. Blanks only, first non-blank sibling wins; nothing is
			 * deleted and no non-empty field is touched. */
			{
				std::unordered_map<std::string, const SpellEntry*> donors;
				for (const auto& s : g_magicConfig.spells) {
					const auto key = MagicIdKey(s.plugin, s.localId);
					if (key.empty())
						continue;
					if (!s.icon.empty() || !s.school.empty() || !s.slot.empty())
						donors.emplace(key, &s);   // first informative row wins
				}
				for (auto& s : g_magicConfig.spells) {
					const auto key = MagicIdKey(s.plugin, s.localId);
					if (key.empty())
						continue;
					const auto it = donors.find(key);
					if (it == donors.end() || it->second == &s)
						continue;
					const bool wasBlank = s.icon.empty();
					MagicFillBlanks(s, *it->second);
					if (wasBlank && !s.icon.empty())
						++metaFixed;
				}
			}

			// --- pass 3: references ------------------------------------------
			// Combo members and the Removed drawer are SNAPSHOTS keyed by the
			// same durable pair, so what they need from a merge is the
			// survivor's art (a member that resolved to the dropped duplicate
			// would otherwise keep drawing the glyph the duplicate had).
			{
				std::unordered_map<std::string, const SpellEntry*> byKey;
				for (const auto& s : g_magicConfig.spells) {
					const auto key = MagicIdKey(s.plugin, s.localId);
					if (!key.empty())
						byKey.emplace(key, &s);
				}
				auto adoptFrom = [&](SpellMeta& m) {
					const auto key = MagicIdKey(m.plugin, m.localId);
					if (key.empty())
						return;
					const auto it = byKey.find(key);
					if (it == byKey.end())
						return;
					const SpellEntry& s = *it->second;
					if (m.icon.empty() && !s.icon.empty()) { m.icon = s.icon; ++metaFixed; }
					if (m.name.empty() && !s.name.empty()) m.name = s.name;
					if (m.school.empty() && !s.school.empty()) m.school = s.school;
					if (m.element.empty() && !s.element.empty()) m.element = s.element;
					if (m.archetype.empty() && !s.archetype.empty()) m.archetype = s.archetype;
					if (m.tier.empty() && !s.tier.empty()) m.tier = s.tier;
				};
				for (auto& m : g_magicConfig.removed)
					adoptFrom(m);
				for (auto& c : g_magicConfig.combos)
					for (auto& m : c.spells)
						adoptFrom(m);
				// The Removed drawer can itself hold two rows for one spell,
				// for exactly the same reason the entries could.
				std::unordered_map<std::string, std::size_t> seenRemoved;
				std::vector<SpellMeta>                       keepRemoved;
				keepRemoved.reserve(g_magicConfig.removed.size());
				for (auto& m : g_magicConfig.removed) {
					const auto key = MagicIdKey(m.plugin, m.localId);
					if (key.empty() || seenRemoved.emplace(key, keepRemoved.size()).second)
						keepRemoved.push_back(std::move(m));
					else
						++merged;
				}
				g_magicConfig.removed = std::move(keepRemoved);
				// Nothing else in the magic slice references a spell ENTRY by
				// its id (combos hold snapshots by construction), so idRemap is
				// diagnostics — logged, not silently dropped.
				if (!idRemap.empty())
					logger::info("magic id repair: {} duplicate entry id(s) folded away", idRemap.size());
			}
		}

		if (!idFixed && !merged && !metaFixed)
			return {};
		std::string names;
		for (std::size_t i = 0; i < mergedNames.size() && i < 6; ++i)
			names += (i ? ", " : "") + mergedNames[i];
		std::string msg = "magic id repair: " + std::to_string(idFixed) + " stale formId(s) re-resolved, " +
						  std::to_string(merged) + " duplicate(s) merged, " + std::to_string(metaFixed) +
						  " snapshot field(s) healed, " + std::to_string(unresolved) + " unresolvable";
		if (!names.empty())
			msg += " [" + names + "]";
		return msg;
	}

	// The Magic Menu capture key: snapshot the highlighted spell, file it into
	// the deck (under the category named like its school when one exists),
	// optionally clear it from the vanilla spellbook (magic.removeOnAdd),
	// persist, notify. The deck entry survives a spellbook removal and stays
	// castable — CastSpellImmediate doesn't require the spell to be known — and
	// the removal lands in the restorable Removed list like any other.
	// Main thread only (reads menu scaleform + mutates the player).
	void DoAddHighlighted()
	{
		const auto snap = json::parse(SpellActions::HighlightedSpellJson(), nullptr, false);
		if (snap.is_discarded() || !snap.value("ok", false)) {
			RE::DebugNotification("Spell Deck: no spell highlighted");
			return;
		}
		const auto plugin = snap.value("plugin", std::string(""));
		const auto localId = snap.value("localId", 0u);
		const auto formId = snap.value("formId", 0u);
		const auto name = snap.value("name", std::string("spell"));
		const auto type = snap.value("type", std::string(""));

		char hex[11];
		std::snprintf(hex, sizeof(hex), "0x%08X", formId);

		bool        removeOnAdd, wasDup = false;
		std::string category;
		{
			std::lock_guard l(g_configMutex);
			removeOnAdd = g_magicConfig.removeOnAdd;
			if (g_magicConfig.categories.empty())
				g_magicConfig.categories = DefaultMagicConfig().categories;
			// File under the category named like the school (case-insensitive) when
			// there is one — "Destruction" catches destruction — else the first.
			category = g_magicConfig.categories.front();
			if (const auto school = snap.value("school", std::string("")); !school.empty()) {
				for (const auto& c : g_magicConfig.categories) {
					std::string lc = c;
					std::transform(lc.begin(), lc.end(), lc.begin(),
						[](unsigned char ch) { return static_cast<char>(std::tolower(ch)); });
					if (lc == school) {
						category = c;
						break;
					}
				}
			}
			/* Duplicate check by DURABLE identity first (plugin, localId), with
			 * the runtime formId only as the fallback for a form that has no
			 * pair (a dynamic 0xFF… id). Keying this on formId alone is what
			 * let Rober re-add "Dragonknight" as a second entry on 2026-08-18:
			 * its plugin's mod index had shifted 0x81 -> 0x80, so the stored id
			 * no longer equalled the live one and the deck saw a new spell. */
			const auto addKey = MagicIdKey(plugin, localId);
			for (const auto& s : g_magicConfig.spells) {
				const bool same = addKey.empty()
					? (s.formId == formId)
					: (MagicIdKey(s.plugin, s.localId) == addKey);
				if (same) {
					wasDup = true;
					category = s.category;  // report where it already lives
					break;
				}
			}
			if (!wasDup) {
				SpellEntry e;
				e.id = hex;
				while (std::any_of(g_magicConfig.spells.begin(), g_magicConfig.spells.end(),
					[&](const SpellEntry& s) { return s.id == e.id; }))
					e.id += "+";
				e.plugin = plugin;
				e.localId = localId;
				e.formId = formId;
				e.name = name;
				e.mode = "cast";
				e.hand = "right";
				e.category = category;
				e.slot = snap.value("slot", std::string(""));
				e.type = snap.value("type", std::string(""));
				e.school = snap.value("school", std::string(""));
				e.element = snap.value("element", std::string(""));
				e.archetype = snap.value("archetype", std::string(""));
				e.tier = snap.value("tier", std::string(""));
				g_magicConfig.spells.push_back(std::move(e));
			}
		}

		// Optional spellbook removal (only real hand spells; RemoveFromSpellbook
		// re-checks). notify=false — the combined notification below covers it.
		bool removed = false;
		if (removeOnAdd && type == "spell") {
			const auto rr = json::parse(
				SpellActions::RemoveFromSpellbook(plugin, localId, formId, false), nullptr, false);
			if (!rr.is_discarded() && rr.value("ok", false)) {
				removed = true;
				SpellMeta m;
				m.plugin = rr.value("plugin", plugin);
				m.localId = rr.value("localId", localId);
				m.formId = rr.value("formId", formId);
				m.name = rr.value("name", name);
				m.type = rr.value("type", type);
				m.school = rr.value("school", std::string(""));
				m.element = rr.value("element", std::string(""));
				m.archetype = rr.value("archetype", std::string(""));
				m.tier = rr.value("tier", std::string(""));
				std::lock_guard l(g_configMutex);
				// Durable pair first here too, or a stale runtime id leaves the
				// old row behind and the drawer grows a second copy.
				const auto rmKey = MagicIdKey(m.plugin, m.localId);
				std::erase_if(g_magicConfig.removed, [&](const SpellMeta& x) {
					return rmKey.empty() ? (x.formId == m.formId)
										 : (MagicIdKey(x.plugin, x.localId) == rmKey);
				});
				g_magicConfig.removed.insert(g_magicConfig.removed.begin(), std::move(m));
			}
		}

		PersistAll();
		std::string note = wasDup ? ("Spell Deck: " + name + " is already in " + category) :
									("Spell Deck: added " + name + " to " + category);
		if (removed)
			note += " (removed from spellbook)";
		RE::DebugNotification(note.c_str());
		logger::info("capture-key: {} ({}) -> '{}'{}{}", name, hex, category,
			wasDup ? " [dup]" : "", removed ? " [removed from spellbook]" : "");
	}

	// ------------------------------------------- Followers tab (deck view)
	// The roster is Follower Organizer's data, reached through its in-process
	// Deck API (follower_deck.h). The pane (followers-pane.js) is thin: it
	// renders whatever state envelope C++ pushes and sends one mutation op at
	// a time; every reply carries fresh state, so the view never owns roster
	// truth. All fd* traffic rides the DECK view (registered in
	// EnsureViewAndOpen); F14 deep-opens the palette onto the tab.

	// The add-follower target: whoever the crosshair snapshot caught at open.
	std::string FolTargetJson()
	{
		const auto id = NpcActions::TargetFormID();
		auto*      actor = id ? RE::TESForm::LookupByID<RE::Actor>(id) : nullptr;
		if (!actor)
			return "null";
		// `following` / `dead` ride along so the quick strip can say the one
		// thing that is actually available (Recruit vs Dismiss) instead of
		// offering both and letting NFF refuse one of them.
		//
		// `wedged` is the third state neither of those covers: the factions say
		// current follower, the engine says not a teammate, and BOTH halves of
		// her follower dialogue are conditioned away (nff_control.h). Without
		// it the card offers Recruit — which is exactly the call that put her
		// there — and the one control that repairs it is unreachable.
		// `imported` is a FOURTH, independent state: NFF's "Add to Framework"
		// is not recruitment, so it is orthogonal to `following` — she can be
		// imported without being a teammate (the normal case: her own follower
		// mod moves her). The card needs it to label one button truthfully as
		// Add or Remove instead of offering both.
		return json{ { "formId", id },
			{ "name", actor->GetDisplayFullName() },
			{ "following", actor->IsPlayerTeammate() },
			{ "wedged", NffControl::IsWedgedFollower(actor) },
			{ "imported", NffControl::IsImported(actor) },
			// A FIFTH state, and the one that makes Dismiss reachable: NFF's
			// OWN follower faction. `following` above is IsPlayerTeammate(),
			// and NFF keeps followers through states the engine does not count
			// as teammate — so without this the card offered Recruit to
			// someone NFF was already managing and hid the only control that
			// would release her (Rober, 2026-09-10).
			{ "nffFollower", NffBridge::IsNffFollower(actor) },
			// Whether the game will let you ask her to follow AT ALL
			// (PotentialFollowerFaction). Most NPCs are not in it — that is
			// what NFF's "Force Follower" grants, so the card only offers it
			// to someone who actually lacks it.
			{ "canFollow", NffControl::CanBeFollower(actor) },
			// …and whether that eligibility is one WE granted, which is the
			// only case where offering to take it away is safe.
			{ "forcedFollow", NffControl::WasForcedFollower(actor) },
			{ "dead", actor->IsDead() } }
			.dump(-1, ' ', false, json::error_handler_t::replace);
	}

	// The ground item under the crosshair at open, resolved to the mod that
	// owns it (the item-source banner's payload). Two plugins matter and they
	// are different questions: the BASE object's defining file answers "what
	// mod adds this item"; the last file in the base's source list is the
	// winning override ("who last edited the record"); and the REFERENCE's
	// defining file is who placed this particular instance in the world — a
	// dropped or spawned item is a runtime 0xFF ref with no file at all, which
	// is reported honestly as empty rather than guessed at.
	std::string ItemSourceJson()
	{
		const auto id = NpcActions::ItemRefFormID();
		auto*      ref = id ? RE::TESForm::LookupByID<RE::TESObjectREFR>(id) : nullptr;
		auto*      base = ref ? ref->GetBaseObject() : nullptr;
		if (!base)
			return "null";

		const auto fileName = [](const RE::TESFile* f) {
			return f ? std::string(f->GetFilename()) : std::string();
		};

		const std::string basePlugin = fileName(base->GetFile(0));
		// Winning override: the LAST file carrying the record. GetFile(-1) is
		// the canonical "last source" accessor — the rig's pinned CommonLib
		// snapshot predates public sourceFiles access, which broke the build
		// here on 2026-08-03.
		std::string winner = fileName(base->GetFile(-1));
		if (winner == basePlugin)
			winner.clear();
		const std::string refPlugin = fileName(ref->GetFile(0));

		const char* disp = ref->GetDisplayFullName();
		std::string name = (disp && disp[0]) ? disp : "";
		if (name.empty()) {
			const char* bn = base->GetName();
			name = (bn && bn[0]) ? bn : "(unnamed object)";
		}

		char baseHex[16];
		std::snprintf(baseHex, sizeof(baseHex), "%08X", base->GetFormID());

		logger::info("open: item-source banner -> \"{}\" [{}] from {}", name,
			baseHex, basePlugin.empty() ? "(dynamic form)" : basePlugin);

		return json{
			{ "name", name },
			{ "baseId", baseHex },
			{ "basePlugin", basePlugin },  // "" = runtime/dynamic form
			{ "override", winner },        // "" = no later override
			{ "refPlugin", refPlugin }     // "" = dropped/spawned in this save
		}
			.dump(-1, ' ', false, json::error_handler_t::replace);
	}

	std::filesystem::path DeckViewDir()
	{
		return std::filesystem::path("Data") / "PrismaUI" / "views" / "HotkeyDeck";
	}

	// Live listing of follower portrait files — the same trick as
	// CustomIconsJson() for the Spell Deck. Re-scanned on EVERY palette open and
	// every fdRefresh, so a file dropped into portraits\ (by hand or by the Deck
	// Portal web app) shows up without a restart: MO2's VFS passes new files in a
	// mounted mod dir straight through.
	//
	// The slug comes from the file stem via PortraitCapture::SlugFromFileStem —
	// `<slug>.png` and `<slug>~<version>.png` both resolve to `<slug>`, and the
	// pane matches that against slugOf(member.original). mtime rides along as a
	// cache-bust token — Ultralight caches view-relative images by URL, so
	// REPLACING a portrait under the same name would otherwise keep painting the
	// old bytes.
	//
	// WHY VERSIONS EXIST AT ALL: Ultralight memory-maps every image it draws and
	// holds it for the session, so a portrait the deck has already SHOWN cannot
	// be overwritten in place — the capture lands beside it as `<slug>~<n>.png`
	// instead. Hence the two rules here: many files may share a slug, and the
	// NEWEST of them is the portrait. The winner's real FILENAME is what goes to
	// the view; it can no longer be rebuilt from slug + ext.
	std::string FolPortraitsJson()
	{
		std::error_code ec;
		const auto      dir = DeckViewDir() / "portraits";
		// Create it so the drop target exists even on a fresh install.
		std::filesystem::create_directories(dir, ec);

		// ---- rescan throttle (BUG C, Rober 2026-08-13) -----------------------
		// The Followers HUD ticker calls this every ~1.2 s (g_hudConfig.tickMs), so
		// a full directory walk + a last_write_time() per file — AND the "portraits:
		// N usable…" log line — fired continuously the whole time the HUD was on.
		// The folder only changes when a portrait is captured, uploaded or deleted;
		// every one of those ADDS or REMOVES a file (the self/follower/portal writes
		// version-then-prune, they never silently rewrite in place), so the
		// directory's own mtime is a faithful change signal. Cache the built JSON and
		// only rebuild when that mtime moves — with a 30 s hard floor so an in-place
		// overwrite (a tool that truncates a file without touching the dir listing)
		// is still picked up. All callers are on the MAIN THREAD (HUD ticker →
		// AddTask, palette open, portal poll → AddTask), so a plain static cache is
		// safe with no lock. The log now fires only when a rebuild actually happens.
		static std::string   s_cache;
		static bool          s_haveCache = false;
		static std::uint64_t s_dirMtime  = 0;      // portraits/ dir mtime, in ticks
		static std::uint64_t s_builtAtSec = 0;     // wall-clock seconds of last build
		{
			std::error_code dec;
			const auto       dft = std::filesystem::last_write_time(dir, dec);
			const std::uint64_t dirMtime = dec ? 0
				: static_cast<std::uint64_t>(dft.time_since_epoch().count());
			const auto nowSec = static_cast<std::uint64_t>(
				std::chrono::duration_cast<std::chrono::seconds>(
					std::chrono::system_clock::now().time_since_epoch()).count());
			// Serve the cache when the dir has not changed AND the 30 s floor has not
			// elapsed. A read error on the dir mtime (dirMtime == 0) forces a rebuild
			// rather than pinning a possibly-stale cache.
			if (s_haveCache && dirMtime != 0 && dirMtime == s_dirMtime &&
				(nowSec - s_builtAtSec) < 30)
				return s_cache;
			s_dirMtime  = dirMtime;
			s_builtAtSec = nowSec;
		}

		// MSVC's file_time_type ticks are 100 ns since 1601-01-01. Shift to the
		// Unix epoch so the value is a readable timestamp in the log and stays
		// well inside the range JS handles exactly.
		constexpr std::uint64_t kTicksPerSec = 10000000ULL;
		constexpr std::uint64_t kWinToUnix   = 11644473600ULL;

		// slug -> the best file seen so far. A map rather than straight-to-array
		// because the winner is only known once the whole folder has been read.
		struct Shot
		{
			std::string   file;    // verbatim, as the view must load it
			std::string   fold;    // lowercased, for the tie-break only
			std::string   ext;
			std::uint64_t mtime = 0;
		};
		std::map<std::string, Shot> best;

		const auto LowerCopy = [](std::string s) {
			std::transform(s.begin(), s.end(), s.begin(),
				[](unsigned char c) { return static_cast<char>(std::tolower(c)); });
			return s;
		};

		std::size_t skipped = 0;
		std::size_t superseded = 0;
		for (std::filesystem::directory_iterator it(dir, ec), end; !ec && it != end; it.increment(ec)) {
			std::error_code fec;
			if (!it->is_regular_file(fec))
				continue;

			auto ext = PathU8(it->path().extension());
			std::transform(ext.begin(), ext.end(), ext.begin(),
				[](unsigned char c) { return static_cast<char>(std::tolower(c)); });
			// Deliberately narrow: no gif/svg. A portrait is a still photo in a
			// 40 px circle; the Deck Portal refuses anything else too.
			if (ext != ".png" && ext != ".jpg" && ext != ".jpeg" && ext != ".webp") {
				++skipped;
				continue;
			}

			const auto slug = PortraitCapture::SlugFromFileStem(PathU8(it->path().stem()));
			if (slug.empty())
				continue;

			// PERF (2026-08-16): `it->last_write_time()`, NOT the free function on
			// the path. The MSVC directory_entry already carries the times the
			// directory enumeration handed back, so the member form is a struct
			// read; the free function re-opens the FILE. This walk runs on the
			// game thread every 30 s (the floor below), and at 87 portraits that
			// was 87 file opens per pass. Same value, same tie-break, no syscall.
			std::uint64_t stamp = 0;
			const auto    ft = it->last_write_time(fec);
			if (!fec) {
				const auto secs = static_cast<std::uint64_t>(ft.time_since_epoch().count()) / kTicksPerSec;
				stamp = secs > kWinToUnix ? secs - kWinToUnix : secs;
			}

			// The name is kept VERBATIM for the view to load — only the comparison
			// key is folded. Windows is case-insensitive so `Elana-Darkfire.JPG`
			// would probably load either way, but handing the loader a name that
			// is not the one on disk is a gamble with nothing to win.
			auto       file = PathU8(it->path().filename());
			const auto fold = LowerCopy(file);

			// THE WINNER RULE, and portal/server.js betterPortrait() must match it
			// exactly or the phone shows one face and the deck draws another:
			// newest mtime wins; on a tie the greater FILENAME wins. The tie-break
			// earns its keep — these stamps are whole seconds, so a re-capture
			// landing in the same second as the file it supersedes is entirely
			// possible. '~' (0x7E) sorts above '.' (0x2E), so `x~1753900000.png`
			// beats `x.png`, and between two versions the later stamp beats the
			// earlier.
			auto&      cur = best[slug];
			const bool wins = cur.file.empty() ||
							  stamp > cur.mtime ||
							  (stamp == cur.mtime && fold > cur.fold);
			if (!cur.file.empty())
				++superseded;
			if (wins) {
				cur.file = std::move(file);
				cur.fold = fold;
				cur.ext = ext.substr(1);   // "png", not ".png"
				cur.mtime = stamp;
			}
		}

		json arr = json::array();
		for (const auto& [slug, shot] : best) {
			arr.push_back(json{
				{ "slug", slug },
				// The real filename, because `<slug>.<ext>` no longer reconstructs
				// it. The view still falls back to that form if `file` is absent,
				// so an older view and a newer DLL do not break each other.
				{ "file", shot.file },
				{ "ext", shot.ext },
				{ "mtime", shot.mtime } });
		}

		// Only logged when a rebuild actually happens (the throttle above returns
		// the cache otherwise), so this no longer spams once per HUD tick.
		if (!arr.empty() || skipped || superseded)
			logger::info("portraits: {} usable, {} superseded (older file for the same follower), {} skipped (unsupported type)",
				arr.size(), superseded, skipped);
		s_cache     = arr.dump(-1, ' ', false, json::error_handler_t::replace);
		s_haveCache = true;
		return s_cache;
	}

	// ------------------------------------------------------- deck icon library
	// The deck view draws per-hotkey icons from ITS OWN icons/ tree: Ultralight
	// resolves an <img src> against the view that loaded the page, so a
	// "../MagicDeck/..." or absolute path is not an option. The deployer
	// robocopies icons/{sh/**, sh_index.json} into view/HotkeyDeck/ as well, and
	// the two indexes are interchangeable because every path inside is
	// view-relative.
	std::string DeckIconIndexJson()
	{
		return IconIndexJsonAt(DeckViewDir() / "icons" / "sh_index.json", "deck");
	}

	// Custom icons arrive in the SPELL DECK's folder — the Deck Portal uploads
	// there and SweepDesktopIcons() sweeps Desktop\Spell Deck Icons there — so
	// mirror them across before the deck scans its own pool. ONE WAY on purpose
	// (MagicDeck stays the single authoring folder, so a stale copy can never
	// win); images only; size-compared, so it is a no-op after the first pass.
	void MirrorCustomIcons(const std::filesystem::path& src, const std::filesystem::path& dst)
	{
		if (const auto copied = CopyNewImages(src, dst, "icon mirror"); copied > 0)
			logger::info("mirrored {} custom icon(s) into the deck view", copied);
	}

	// Defined with the HUD view machinery below; used by DeckCustomIconsJson so a
	// mid-session icon change reaches the HotkeyDeck tree without a relaunch.
	void MirrorSpellIconsAsync();
	void MirrorSpellIconsAsync(std::function<void()> onDone);

	// Cheap "did this folder's file SET change" probe: the directory's own
	// last_write_time, which NTFS bumps on entry create/delete/rename. One syscall,
	// no per-file stat. Content-in-place edits do not bump it, and that is exactly
	// right here — the icon listing below is filenames + stems, never file bytes,
	// so a same-name overwrite cannot change the output anyway. 0 on a missing dir
	// (which also differs from a populated dir, so first population is caught).
	std::uint64_t DirGeneration(const std::filesystem::path& dir)
	{
		std::error_code ec;
		const auto ft = std::filesystem::last_write_time(dir, ec);
		if (ec)
			return 0;
		return static_cast<std::uint64_t>(ft.time_since_epoch().count());
	}

	// Live listing for the deck's icon picker: sweep the desktop drop folder,
	// mirror magic -> deck, then enumerate the deck's own folder.
	//
	// This ran in FULL on every palette open — three create_directories, three
	// directory enumerations (Desktop drop + MagicDeck custom + HotkeyDeck custom)
	// and a per-file stat on each — and it grows with the player's icon collection.
	// On an HDD that is real, repeated open-latency (the public "slow to load"
	// complaint). So the steady state is now GATED: if none of the three source
	// folders' generations changed since last time, return the cached listing and
	// touch the disk zero times. `forceRescan` (the picker's Refresh) always does
	// the real work. Main-thread only; the cache is a plain static.
	std::string DeckCustomIconsJson(bool forceRescan)
	{
		const auto magicDir  = MagicViewDir() / "icons" / "custom";
		const auto deckDir   = DeckViewDir() / "icons" / "custom";
		const char* prof     = std::getenv("USERPROFILE");
		const auto dropDir   = (prof && *prof)
			? std::filesystem::path(prof) / "Desktop" / "Spell Deck Icons"
			: std::filesystem::path();

		static std::string   s_cache;
		static bool          s_have = false;
		static std::uint64_t s_dropGen = 0, s_magicGen = 0, s_deckGen = 0;

		const std::uint64_t dropGen  = dropDir.empty() ? 0 : DirGeneration(dropDir);
		const std::uint64_t magicGen = DirGeneration(magicDir);
		const std::uint64_t deckGen  = DirGeneration(deckDir);

		if (!forceRescan && s_have &&
		    dropGen == s_dropGen && magicGen == s_magicGen && deckGen == s_deckGen)
			return s_cache;   // nothing added/removed in any source folder -> reuse

		SweepDesktopIcons(magicDir);   // may create+populate magicDir (bumps magicGen)
		MirrorCustomIcons(magicDir, deckDir);
		// A real rescan means an icon folder CHANGED — re-run the HUD's spell-pool
		// mirror too (worker thread, skip-existing, no-op when nothing is new), so
		// art uploaded or dropped mid-session reaches the HotkeyDeck tree the HUD
		// and hotbar read NOW instead of after the next launch (the old "honest
		// limit" in MirrorSpellIconsAsync — closed 2026-08-19).
		MirrorSpellIconsAsync();
		s_cache = CustomIconsJsonIn(deckDir);
		s_have  = true;
		// Re-probe AFTER the sweep/mirror: those two just changed the folders we are
		// caching against, so record the post-write generations or the very next
		// open would see a mismatch and rescan for nothing.
		s_dropGen  = dropDir.empty() ? 0 : DirGeneration(dropDir);
		s_magicGen = DirGeneration(magicDir);
		s_deckGen  = DirGeneration(deckDir);
		return s_cache;
	}

	// hdIconList: the deck picker's Refresh — re-scan and re-push right now.
	// Deliberately does NOT re-push hdOpen (that would reset the tab / edit mode /
	// search); the view merges the new listing into its icon library only. FORCES
	// a fresh scan (the whole point of a Refresh button is to pick up a drop the
	// generation gate would otherwise have to notice on its own).
	void OnJsIconList(const char*)
	{
		SKSE::GetTaskInterface()->AddTask([]() {
			const auto listing = DeckCustomIconsJson(true);
			PushToView("hdIcons", listing);
			// ...and the HUD's widget-background picker keeps step: a fresh
			// upload/drop is choosable there without waiting for a relaunch.
			if (g_prisma && g_hudView)
				g_prisma->Invoke(g_hudView, ("hudCustomIcons(" + listing + ")").c_str());
		});
	}

	// hdOpenSpells: the "Spells" launcher in the deck's top nav. PrismaUI focus is
	// single-view, so ours must let go FIRST and the handover happens on a SECOND
	// task hop — CanOpenNow() gates on HasAnyActiveFocus() and on the pause the
	// deck was holding, and neither is guaranteed to have settled in the same
	// frame as the Unfocus. Same nested-AddTask shape OnJsFolWorld already uses.
	void OnJsOpenSpells(const char* data)
	{
		// Optional payload: "arts" deep-opens the Spell Deck on its Combat Arts
		// page (the Home card / omni row / the bindable action). Anything else
		// — including the empty string every older caller sends — is the spell
		// list, so this stays backwards compatible with a stale view.
		const std::string page = (data && std::string(data) == "arts") ? "arts" : "";
		SKSE::GetTaskInterface()->AddTask([page]() {
			g_magicPendingPage = page;
			ClosePalette();
		});
		// ClosePalette() only STARTS the handoff: PrismaUI still owns focus (and
		// the pause with it) for a frame or more afterwards, so CanOpenNow() is
		// reliably FALSE on the very next task — which is how this shipped, and
		// why the launcher answered "use F18" every single time (play-tested
		// 2026-07-30 12:26). A click is an explicit request, so give the handoff
		// a real budget instead of one frame. Same detached-sleep-then-AddTask
		// idiom as FireAndClose().
		std::thread([]() {
			using namespace std::chrono;
			for (int i = 0; i < 15; ++i) {  // ~1.2 s, then give up loudly
				std::this_thread::sleep_for(milliseconds(80));
				if (g_magicOpen.load())
					return;  // open — the click landed
				SKSE::GetTaskInterface()->AddTask([]() {
					// Re-checked on the main thread: CanOpenNow() reads live UI state.
					if (!g_magicOpen.load() && CanOpenNow())
						EnsureMagicViewAndOpen();
				});
			}
			SKSE::GetTaskInterface()->AddTask([]() {
				if (g_magicOpen.load())
					return;
				// Never fail silently: the player clicked something.
				logger::warn("hdOpenSpells: focus/pause never cleared after ~1.2 s");
				// ASCII only: the notification bar renders the game's own
				// encoding, not UTF-8 (every other literal here follows suit).
				RE::DebugNotification("Spell Deck unavailable right now - use the F18 key");
			});
		}).detach();
	}

	// ------------------------------------------- Deck Portal NPC-field handoff
	// The Deck Portal (portal/server.js) lets a phone set a follower's
	// relationship/home/… while the game is running. It deliberately NEVER
	// writes FollowerOrganizer.json: FO holds the whole roster in memory and
	// rewrites that file wholesale on every SaveSettings(), so a portal write
	// would be clobbered by the next in-game rename — silently, and after
	// burning a rotating-backup slot. Instead the portal drops a sidecar in the
	// deck's view folder and we replay it HERE, through the FO Deck API, so FO
	// itself performs the write exactly as if the edit came from the pane.
	//
	//   { "version": 1,
	//     "set": [ { "original": "<Member.OriginalName>",
	//                "key": "relationship", "value": "wife" } ] }
	//
	// Addressed by ORIGINAL NAME, never cat/idx: those shift the moment anyone
	// reorders or re-files someone in-game, and the portal's snapshot of them can
	// be minutes stale. setFieldByOriginal applies to EVERY entry with that name,
	// so a person filed in two categories can't end up disagreeing with herself.
	// "" clears the field. Unknown names are skipped (FO returns a message we
	// log); a malformed file is logged and discarded rather than retried forever.
	//
	// MAIN THREAD ONLY — FollowerDeck::Apply touches FO's roster and live actors.
	// v0.11.0: also replayed by PortalPollLoop()'s main-thread task (gated on
	// g_gameReady, because the roster does not exist on the main menu). Returns
	// true when at least one field write was accepted, so the poller re-pushes
	// fdState only on real news.

	// Minimal base64 -> bytes. No dependency, and the only caller is the portal
	// portrait bridge, which hands us an image a phone just encoded.
	std::vector<std::uint8_t> DecodeBase64(const std::string& in)
	{
		auto val = [](unsigned char c) -> int {
			if (c >= 'A' && c <= 'Z') return c - 'A';
			if (c >= 'a' && c <= 'z') return c - 'a' + 26;
			if (c >= '0' && c <= '9') return c - '0' + 52;
			if (c == '+') return 62;
			if (c == '/') return 63;
			return -1;               // '=' and any whitespace/newline
		};
		std::vector<std::uint8_t> out;
		out.reserve(in.size() * 3 / 4);
		int acc = 0, bits = 0;
		for (const unsigned char c : in) {
			const int v = val(c);
			if (v < 0) continue;     // skip padding and stray whitespace
			acc = (acc << 6) | v;
			bits += 6;
			if (bits >= 8) {
				bits -= 8;
				out.push_back(static_cast<std::uint8_t>((acc >> bits) & 0xFF));
			}
		}
		return out;
	}

	// ------------------------------------------------- portal portraits (live)
	//
	//  WHY THIS EXISTS: a portrait cropped on the phone used to be invisible in
	//  game until the next launch. MO2 snapshots the directory LISTING at start,
	//  so a file the portal newly creates in the mod folder is not there as far
	//  as the running game is concerned — the scanner iterates the folder and
	//  simply never sees it. (A direct open by exact path DOES resolve, which is
	//  why the sidecars below work at all.)
	//
	//  So the portal stops writing the image itself and hands us the BYTES. Our
	//  write goes through the VFS from inside the game, exactly like an in-game
	//  capture, so the file lands in overwrite and the very next scan finds it.
	//  The portal is no longer writing image files into a mod folder the game has
	//  open — which it never should have been.
	bool ApplyPortalPortraits()
	{
		const auto      file = DeckViewDir() / "portal-portraits.json";
		std::error_code ec;
		if (!std::filesystem::exists(file, ec))
			return false;

		std::string text;
		{
			std::ifstream in(file, std::ios::binary);
			if (!in.is_open()) {
				logger::warn("portal portraits present but unreadable — retrying");
				return false;
			}
			text.assign((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
		}

		const auto j = json::parse(text, nullptr, false);
		std::size_t wrote = 0;
		if (j.is_discarded() || !j.is_object() || !j["shots"].is_array()) {
			logger::error("portal portraits file is malformed — discarding it");
		} else {
			const auto dir = DeckViewDir() / "portraits";
			std::filesystem::create_directories(dir, ec);
			for (const auto& e : j["shots"]) {
				if (!e.is_object())
					continue;
				const auto slug = PortraitCapture::SlugOfName(e.value("slug", std::string("")));
				auto       ext = e.value("ext", std::string("jpg"));
				const auto b64 = e.value("dataBase64", std::string(""));
				if (slug.empty() || b64.empty())
					continue;
				if (ext != "png" && ext != "jpg" && ext != "jpeg" && ext != "webp")
					ext = "jpg";
				const auto bytes = DecodeBase64(b64);
				if (bytes.empty()) {
					logger::warn("portal portrait '{}' did not decode — skipped", slug);
					continue;
				}
				// Same lock rule as the capture: a portrait the deck has already
				// DRAWN is memory-mapped and cannot be overwritten, so fall back
				// to a versioned name the scanner resolves back to this slug.
				if (!PortraitCapture::WritePortraitBytes(dir, slug, ext, bytes))
					logger::warn("portal portrait '{}' could not be written", slug);
				else
					++wrote;
			}
		}

		// TRUNCATE, never delete. MO2 snapshots the directory LISTING at launch,
		// so a file the portal CREATES mid-session is invisible to the running
		// game — but an edit to a file that already existed is seen. Deleting the
		// bridge after every batch therefore made the next phone upload a create,
		// and the queue silently never arrived. (Proven 2026-08-02: ysolda.jpg and
		// a 202 KB portal-portraits.json both on disk, zero "portal portrait"
		// lines in the log, because the game launched ten minutes earlier.)
		// Writing an empty queue back keeps the file — and its VFS visibility —
		// alive for the next one.
		EnsurePortraitBridge(true);
		if (wrote)
			logger::info("portal portraits: wrote {} through the VFS - visible without a relaunch", wrote);
		return wrote > 0;
	}

	// ------------------------------------ portal category icons (followers rail)
	//
	//  The phone's half of v0.14's category glyphs. Shape:
	//
	//    { "version": 1,
	//      "set": [ { "cat": 3, "icon": "icons/custom/hd-shield.png" } ] }
	//
	//  "" clears one. Keyed by the FO category SLOT INDEX for exactly the reason
	//  the in-game picker is (see FollowerConfig::catIcons): the label is
	//  renameable — from this very portal — so a name key would orphan the glyph
	//  the moment "Housecarls" became "Housecarls (Whiterun)".
	//
	//  CONFIG-ONLY, so unlike the fo-ops/npc-field sidecars this needs no loaded
	//  save, no roster and no main thread: it is applied straight on the poller's
	//  own worker thread, exactly like the hotkey-icon sidecar, and works at the
	//  main menu. Validation is the SAME pair of rules as every other writer of
	//  this map — a real slot index and a path ValidViewIconPath accepts —
	//  because the portal is just another untrusted input here.
	bool ApplyPortalCatIcons()
	{
		const auto      file = DeckViewDir() / "portal-cat-icons.json";
		std::error_code ec;
		if (!std::filesystem::exists(file, ec))
			return false;

		std::string text;
		{
			std::ifstream in(file, std::ios::binary);
			if (!in.is_open()) {
				// Held open by the portal mid-write: leave it, next tick gets it.
				logger::warn("portal category icons present but unreadable — retrying");
				return false;
			}
			text.assign((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
		}

		const auto  j = json::parse(text, nullptr, false);
		std::size_t applied = 0, skipped = 0;
		if (j.is_discarded() || !j.is_object() || !j.contains("set") || !j["set"].is_array()) {
			logger::error("portal category icons file is malformed — discarding it");
		} else {
			for (const auto& e : j["set"]) {
				if (!e.is_object())
					continue;
				if (!e.contains("cat") || !e["cat"].is_number_integer()) { ++skipped; continue; }
				const int idx = e["cat"].get<int>();
				if (idx < 0 || idx > kFolCatMax) {
					++skipped;
					logger::info("portal category icon for slot {} skipped: outside 0..{}", idx, kFolCatMax);
					continue;
				}
				auto path = e.value("icon", std::string(""));
				// Empty is the legal CLEAR, so it is checked before the path guard
				// (which also accepts "" — this branch is what makes the intent
				// explicit rather than incidental).
				const bool clear = path.empty();
				if (!clear && !ValidViewIconPath(path)) {
					++skipped;
					logger::info("portal category icon for slot {} refused: '{}' is not a view-relative icons/ path",
						idx, e.value("icon", std::string("")));
					continue;
				}
				{
					std::lock_guard l(g_configMutex);
					if (clear) {
						g_folConfig.catIcons.erase(idx);
					} else if (g_folConfig.catIcons.size() < kMaxCatIcons ||
						g_folConfig.catIcons.count(idx)) {
						// Same ceiling rule as the portrait crops: only a NEW key is
						// refused when the map is full, so re-skinning a category
						// that already has a glyph always works.
						g_folConfig.catIcons[idx] = path;
					} else {
						++skipped;
						continue;
					}
				}
				++applied;
				logger::info("portal category icon: slot {} -> {}", idx, clear ? std::string("(none)") : path);
			}
		}

		if (applied) {
			if (!PersistAll())
				logger::error("portal category icons: applied but failed to write to disk");
			logger::info("portal category icons: {} set, {} skipped", applied, skipped);
		} else if (skipped) {
			logger::info("portal category icons: 0 set, {} skipped", skipped);
		}

		// TRUNCATE, never delete — the portrait bridge's law, and the same MO2
		// listing-snapshot reason: a file the portal has to CREATE mid-session is
		// invisible to the running game, so the empty queue is written back to
		// keep this one alive for the next batch.
		EnsureCatIconBridge(true);
		return applied > 0;
	}

	// The phone's Containers queue, replayed. Two kinds of op with two very
	// different contracts:
	//
	//   CONFIG ("mark" / "sort") — a flag on a container or a global setting.
	//   Applies whether or not a save is loaded, persists, and is what the phone
	//   folds onto its own view so a toggle looks instant.
	//
	//   VERBS ("act") — put-it-all-away, sort, gather, unload, retrieve. These
	//   MOVE ITEMS, so they need a live world and the main thread. At the main
	//   menu they are DROPPED with a log line rather than held: a sweep that
	//   fires an hour later, in a different cell, is not what was pressed.
	//
	// Main thread only (the verbs walk inventories). Returns true when config
	// changed, so the caller knows whether to persist + repaint.
	bool ApplyPortalContainers()
	{
		const auto      file = DeckViewDir() / "portal-containers.json";
		std::error_code ec;
		if (!std::filesystem::exists(file, ec))
			return false;

		std::string text;
		{
			std::ifstream in(file, std::ios::binary);
			if (!in.is_open()) {
				logger::warn("portal containers present but unreadable — retrying");
				return false;
			}
			text.assign((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
		}

		const auto j = json::parse(text, nullptr, false);
		if (j.is_discarded() || !j.is_object() || !j.contains("ops") || !j["ops"].is_array()) {
			logger::error("portal containers file is malformed — discarding it");
			EnsureContainersBridge(true);
			return false;
		}

		// Is there a world to act in? A verb at the main menu is dropped, not held.
		bool inGame = false;
		{
			auto* player = RE::PlayerCharacter::GetSingleton();
			auto* ui = RE::UI::GetSingleton();
			inGame = player && player->GetParentCell() && ui &&
				!ui->IsMenuOpen(RE::MainMenu::MENU_NAME) &&
				!ui->IsMenuOpen(RE::LoadingMenu::MENU_NAME);
		}

		std::size_t             applied = 0, dropped = 0;
		std::vector<json>       verbs;
		for (const auto& e : j["ops"]) {
			if (!e.is_object())
				continue;
			const auto op = e.value("op", std::string(""));

			if (op == "act") {
				if (!inGame) {
					++dropped;
					continue;
				}
				verbs.push_back(e);
				continue;
			}

			if (op == "mark") {
				const auto id = e.value("id", std::string(""));
				const auto key = e.value("key", std::string(""));
				if (id.empty() || key.empty())
					continue;
				std::lock_guard l(g_configMutex);
				for (auto& m : g_contConfig.marks) {
					if (m.id != id)
						continue;
					if (key == "lend")
						m.lend = e.value("value", false);
					else if (key == "ruleEnabled")
						m.sortRule.enabled = e.value("value", false);
					else if (key == "acknowledged")
						m.safeAcknowledged = e.value("value", false);
					else if (key == "redirectTo")
						m.redirectTo = e.value("value", std::string(""));
					else
						break;   // unknown key: not our business, not an error
					++applied;
					logger::info("portal containers: {} {} on '{}'", key,
						e.value("value", false) ? "on" : "set", m.name);
					break;
				}
				continue;
			}

			if (op == "sort") {
				const auto key = e.value("key", std::string(""));
				if (key.empty())
					continue;
				std::lock_guard l(g_configMutex);
				auto&           st = g_contConfig.sort;
				if (key == "inbox") {
					const auto want = e.value("value", std::string(""));
					// A drop-box that names no real mark would be a silent no-op
					// in every later sort, so refuse it here where we can say so.
					const bool known = want.empty() ||
						std::any_of(g_contConfig.marks.begin(), g_contConfig.marks.end(),
							[&want](const ContainerMark& m) { return m.id == want; });
					if (!known) {
						logger::info("portal containers: drop-box '{}' is not a marked container — ignored", want);
						continue;
					}
					st.inboxMarkId = want;
				} else if (key == "sortOnClose") {
					st.sortOnClose = e.value("value", false);
				} else if (key == "excludeEquipped") {
					st.excludeEquipped = e.value("value", true);
				} else if (key == "excludeFavorited") {
					st.excludeFavorited = e.value("value", true);
				} else if (key == "excludeQuest") {
					st.excludeQuest = e.value("value", true);
				} else if (key.rfind("loan.", 0) == 0) {
					const auto which = key.substr(5);
					const bool v = e.value("value", false);
					if (which == "enabled") st.loan.enabled = v;
					else if (which == "smithing") st.loan.smithing = v;
					else if (which == "smelting") st.loan.smelting = v;
					else if (which == "tanning") st.loan.tanning = v;
					else if (which == "cooking") st.loan.cooking = v;
					else if (which == "alchemy") st.loan.alchemy = v;
					else if (which == "enchanting") st.loan.enchanting = v;
					else if (which == "returnOnExit") st.loan.returnOnExit = v;
					else continue;
				} else {
					continue;
				}
				++applied;
				logger::info("portal containers: sort setting '{}' applied", key);
				continue;
			}
		}

		if (applied) {
			if (!PersistAll())
				logger::error("portal containers: applied but failed to write to disk");
			logger::info("portal containers: {} setting(s) applied", applied);
		}
		if (dropped)
			logger::info("portal containers: {} action(s) dropped — no game loaded to run them in", dropped);

		// The verbs run AFTER the config, so a "turn this container on, then put
		// it all away" pair from one phone screen does what it looks like.
		for (const auto& v : verbs) {
			const auto act = v.value("act", std::string(""));
			const int  keep = v.value("keep", 0);
			const int  only = v.value("only", 0);
			std::vector<std::string> types;
			if (v.contains("types") && v["types"].is_array())
				for (const auto& t : v["types"])
					if (t.is_string() && !t.get<std::string>().empty())
						types.push_back(t.get<std::string>());

			ContainerSort::MoveReport rep;
			const char*               opName = "sweep";
			if (act == "sweep") {
				rep = ContainerSort::SweepAll(keep, only);
			} else if (act == "sortNow") {
				opName = "sort";
				rep = ContainerSort::SortDropBox();
			} else if (act == "gather") {
				opName = "gather";
				rep = ContainerSort::GatherAll(types, keep);
			} else if (act == "unload") {
				opName = "unload";
				rep = ContainerSort::UnloadTo(v.value("markId", std::string("")), keep, only);
			} else if (act == "retrieve") {
				opName = "retrieve";
				rep = ContainerSort::RetrieveFrom(v.value("markId", std::string("")), keep, types);
			} else {
				continue;
			}
			if (!rep.msg.empty())
				RE::DebugNotification(rep.msg.c_str());
			json byC = json::array();
			for (const auto& b : rep.byContainer)
				byC.push_back(json{ { "markId", b.markId }, { "name", b.name }, { "count", b.count } });
			PushToView("csResult", json{ { "ok", !rep.refused }, { "op", opName },
										   { "moved", rep.moved }, { "byContainer", std::move(byC) },
										   { "residue", rep.residue }, { "skipped", json::array() },
										   { "msg", rep.msg } }
										   .dump(-1, ' ', false, json::error_handler_t::replace));
			logger::info("portal containers: '{}' from the phone -> {}", act, rep.msg);
		}

		// TRUNCATE, never delete (the portrait-bridge law).
		EnsureContainersBridge(true);
		return applied > 0;
	}

	// The Spell Deck twin of ApplyPortalCatIcons above: entries are
	// { cat: "<category name>", icon: "icons/custom/x.png" | "" }, applied into
	// g_magicConfig.catIcons. A name the rail doesn't currently hold is stored
	// anyway — the portal validates against the live rail, and an entry for a
	// category re-added later is a feature, not a leak (the map is capped).
	bool ApplyPortalSpellCatIcons()
	{
		const auto      file = MagicViewDir() / "portal-spell-cat-icons.json";
		std::error_code ec;
		if (!std::filesystem::exists(file, ec))
			return false;

		std::string text;
		{
			std::ifstream in(file, std::ios::binary);
			if (!in.is_open()) {
				logger::warn("portal spell-category icons present but unreadable — retrying");
				return false;
			}
			text.assign((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
		}

		const auto  j = json::parse(text, nullptr, false);
		std::size_t applied = 0, skipped = 0;
		if (j.is_discarded() || !j.is_object() || !j.contains("set") || !j["set"].is_array()) {
			logger::error("portal spell-category icons file is malformed — discarding it");
		} else {
			for (const auto& e : j["set"]) {
				if (!e.is_object())
					continue;
				if (!e.contains("cat") || !e["cat"].is_string()) { ++skipped; continue; }
				const auto name = e["cat"].get<std::string>();
				if (name.empty() || name.size() > 64) { ++skipped; continue; }
				auto       path = e.value("icon", std::string(""));
				const bool clear = path.empty();
				if (!clear && !ValidViewIconPath(path)) {
					++skipped;
					logger::info("portal spell-category icon for '{}' refused: '{}' is not a view-relative icons/ path",
						name, e.value("icon", std::string("")));
					continue;
				}
				{
					std::lock_guard l(g_configMutex);
					if (clear) {
						g_magicConfig.catIcons.erase(name);
					} else if (g_magicConfig.catIcons.size() < kMaxSpellCatIcons ||
						g_magicConfig.catIcons.count(name)) {
						g_magicConfig.catIcons[name] = path;
					} else {
						++skipped;
						continue;
					}
				}
				++applied;
				logger::info("portal spell-category icon: '{}' -> {}", name, clear ? std::string("(none)") : path);
			}
		}

		if (applied) {
			if (!PersistAll())
				logger::error("portal spell-category icons: applied but failed to write to disk");
			logger::info("portal spell-category icons: {} set, {} skipped", applied, skipped);
		} else if (skipped) {
			logger::info("portal spell-category icons: 0 set, {} skipped", skipped);
		}

		EnsureSpellCatIconBridge(true);  // truncate, never delete — same law as every bridge
		return applied > 0;
	}

	bool ApplyPortalNpcFields()
	{
		const auto      file = DeckViewDir() / "portal-npc-fields.json";
		std::error_code ec;
		if (!std::filesystem::exists(file, ec))
			return false;

		std::string text;
		{
			std::ifstream in(file, std::ios::binary);
			if (!in.is_open()) {
				// Held open by the portal mid-write: leave it, next open gets it.
				logger::warn("portal npc fields present but unreadable — retrying");
				return false;
			}
			text.assign((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
		}

		const auto  j = json::parse(text, nullptr, false);
		std::size_t applied = 0;  // hoisted: the poller needs it after the block
		if (j.is_discarded() || !j.is_object() || !j.contains("set") || !j["set"].is_array()) {
			logger::error("portal npc fields file is malformed — discarding it");
		} else {
			std::size_t skipped = 0;
			for (const auto& e : j["set"]) {
				if (!e.is_object())
					continue;
				const auto original = e.value("original", std::string(""));
				const auto key = e.value("key", std::string(""));
				if (original.empty() || key.empty())
					continue;
				// Straight through the same API the pane uses — FO validates the
				// key, trims/caps the value, erases on "" and saves its own JSON.
				const json cmd{ { "op", "setFieldByOriginal" },
					{ "original", original },
					{ "key", key },
					{ "value", e.value("value", std::string("")) } };
				const auto res = json::parse(FollowerDeck::Apply(cmd.dump(-1, ' ', false, nlohmann::json::error_handler_t::replace)), nullptr, false);
				if (!res.is_discarded() && res.value("ok", false)) {
					++applied;
					logger::info("portal npc field: '{}' {} -> '{}'", original, key,
						e.value("value", std::string("")));
				} else {
					++skipped;
					logger::info("portal npc field for '{}' skipped: {}", original,
						res.is_discarded() ? std::string("bad reply") : res.value("msg", std::string("?")));
				}
			}
			if (applied || skipped)
				logger::info("portal npc fields: {} applied, {} skipped", applied, skipped);
		}

		// Consume it either way — a file we could not apply must not be retried
		// forever. If the delete is refused, blank it so the portal stops showing
		// the change as still pending.
		std::filesystem::remove(file, ec);
		if (ec) {
			logger::warn("could not delete portal npc fields ({}) — blanking instead", ec.message());
			std::ofstream out(file, std::ios::binary | std::ios::trunc);
			if (out.is_open())
				out << R"({"version":1,"set":[]})";
		}
		return applied > 0;
	}

	// -------------------------------- Deck Portal category-ops handoff
	// portal-fo-ops.json: category MOVE + RENAME queued by the phone. Same law and
	// same shape of handler as ApplyPortalNpcFields() above — read, apply each op
	// through the FO Deck API, consume the file either way. A MOVE is name-keyed, so
	// it is resolved to the follower's live cat/idx off a fresh StateJson() before
	// calling moveMember (see src/portal-fo-ops-wiring.md).
	//
	// MAIN THREAD ONLY — needs a loaded save (FO roster) and touches actors.
	// Returns true when at least one op was accepted, so the poller re-pushes
	// fdState only on real news.
	bool ApplyPortalFollowerOps()
	{
		const auto      file = DeckViewDir() / "portal-fo-ops.json";
		std::error_code ec;
		if (!std::filesystem::exists(file, ec))
			return false;

		std::string text;
		{
			std::ifstream in(file, std::ios::binary);
			if (!in.is_open()) {
				// Held open by the portal mid-write: leave it, next tick gets it.
				logger::warn("portal fo-ops present but unreadable — retrying");
				return false;
			}
			text.assign((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
		}

		const auto  j = json::parse(text, nullptr, false);
		std::size_t applied = 0;
		if (j.is_discarded() || !j.is_object() || !j.contains("ops") || !j["ops"].is_array()) {
			logger::error("portal fo-ops file is malformed — discarding it");
		} else {
			std::size_t skipped = 0;

			// One StateJson snapshot for the whole batch — resolve every MOVE name
			// against it. Renames don't need it (they carry the slot directly), but
			// building it once is cheap and keeps the two paths uniform.
			const auto state = json::parse(FollowerDeck::StateJson(), nullptr, false);

			// original (lowercased) -> {cat, idx}, first occurrence wins.
			auto resolve = [&](const std::string& original) -> std::optional<std::pair<int, int>> {
				if (state.is_discarded() || !state.contains("categories"))
					return std::nullopt;
				std::string want = original;
				std::transform(want.begin(), want.end(), want.begin(),
					[](unsigned char ch) { return static_cast<char>(std::tolower(ch)); });
				for (const auto& c : state["categories"]) {
					const int cat = c.value("index", -1);
					if (cat < 1 || !c.contains("members"))
						continue;
					int idx = 0;
					for (const auto& m : c["members"]) {
						std::string got = m.value("original", std::string(""));
						std::transform(got.begin(), got.end(), got.begin(),
							[](unsigned char ch) { return static_cast<char>(std::tolower(ch)); });
						if (got == want)
							return std::make_pair(cat, idx);
						++idx;
					}
				}
				return std::nullopt;
			};

			for (const auto& e : j["ops"]) {
				if (!e.is_object())
					continue;
				const auto type = e.value("type", std::string(""));

				if (type == "move") {
					const auto original = e.value("original", std::string(""));
					const int  toCat = e.value("toCat", -1);
					if (original.empty() || toCat < 1) { ++skipped; continue; }
					const auto hit = resolve(original);
					if (!hit) {
						++skipped;
						logger::info("portal fo move for '{}' skipped: not in the roster", original);
						continue;
					}
					const json cmd{ { "op", "moveMember" },
						{ "cat", hit->first }, { "idx", hit->second }, { "to", toCat } };
					const auto res = json::parse(FollowerDeck::Apply(cmd.dump(-1, ' ', false, nlohmann::json::error_handler_t::replace)), nullptr, false);
					// moveMember returns "" (empty message) on success; the FO Deck
					// API wraps that as {"ok":true}. Match ApplyPortalNpcFields().
					if (!res.is_discarded() && res.value("ok", false)) {
						++applied;
						logger::info("portal fo move: '{}' ({},{}) -> slot {}", original,
							hit->first, hit->second, toCat);
					} else {
						++skipped;
						logger::info("portal fo move for '{}' skipped: {}", original,
							res.is_discarded() ? std::string("bad reply") : res.value("msg", std::string("?")));
					}

				} else if (type == "delete") {
					// Take her off the roster entirely (Rober: "ability to delete
					// followers as well form web app is needed").
					//
					// Keyed by ORIGINAL NAME for the same reason move is, only more
					// so: a delete SHIFTS every index after it, so a batch holding
					// two deletes addressed by position would get the second one
					// wrong. Resolving each name against a snapshot taken before
					// the batch has the same flaw, so this one re-resolves against
					// LIVE state per op rather than using `resolve`.
					//
					// This removes her from Follower Organizer's list. It does not
					// dismiss, disable or otherwise touch the actor — FO is a
					// filing cabinet and this is un-filing her.
					const auto original = e.value("original", std::string(""));
					if (original.empty()) { ++skipped; continue; }

					const auto live = json::parse(FollowerDeck::StateJson(), nullptr, false);
					std::optional<std::pair<int, int>> hit;
					if (!live.is_discarded() && live.contains("categories")) {
						std::string want = original;
						std::transform(want.begin(), want.end(), want.begin(),
							[](unsigned char ch) { return static_cast<char>(std::tolower(ch)); });
						for (const auto& c : live["categories"]) {
							const int cat = c.value("index", -1);
							if (cat < 1 || !c.contains("members"))
								continue;
							int idx = 0;
							for (const auto& m : c["members"]) {
								std::string got = m.value("original", m.value("name", std::string("")));
								std::transform(got.begin(), got.end(), got.begin(),
									[](unsigned char ch) { return static_cast<char>(std::tolower(ch)); });
								if (got == want) { hit = std::make_pair(cat, idx); break; }
								++idx;
							}
							if (hit)
								break;
						}
					}
					if (!hit) {
						++skipped;
						logger::info("portal fo delete for '{}' skipped: not in the roster", original);
						continue;
					}
					const json cmd{ { "op", "deleteMember" },
						{ "cat", hit->first }, { "idx", hit->second } };
					const auto res = json::parse(FollowerDeck::Apply(cmd.dump(-1, ' ', false, nlohmann::json::error_handler_t::replace)), nullptr, false);
					if (!res.is_discarded() && res.value("ok", false)) {
						++applied;
						logger::info("portal fo delete: '{}' removed from slot {}", original, hit->first);
					} else {
						++skipped;
						logger::info("portal fo delete for '{}' skipped: {}", original,
							res.is_discarded() ? std::string("bad reply") : res.value("msg", std::string("?")));
					}

				} else if (type == "setDesc") {
					// The NOTE under a follower's name — FO's own Description
					// field, which the deck has always been able to type into
					// and the phone could only READ ("be nice if i could edit
					// their sub-text in web app"). Same resolve-by-name rule as
					// the others; "" is a legal value and clears it.
					const auto original = e.value("original", std::string(""));
					if (original.empty()) { ++skipped; continue; }
					const auto hit = resolve(original);
					if (!hit) {
						++skipped;
						logger::info("portal fo note for '{}' skipped: not in the roster", original);
						continue;
					}
					const json cmd{ { "op", "setDesc" },
						{ "cat", hit->first }, { "idx", hit->second },
						{ "desc", e.value("desc", std::string("")) } };
					const auto res = json::parse(FollowerDeck::Apply(cmd.dump(-1, ' ', false, nlohmann::json::error_handler_t::replace)), nullptr, false);
					if (!res.is_discarded() && res.value("ok", false)) {
						++applied;
						logger::info("portal fo note: '{}' updated", original);
					} else {
						++skipped;
						logger::info("portal fo note for '{}' skipped: {}", original,
							res.is_discarded() ? std::string("bad reply") : res.value("msg", std::string("?")));
					}

				} else if (type == "renameCategory") {
					const int cat = e.value("cat", -1);
					if (cat < 1) { ++skipped; continue; }
					const json cmd{ { "op", "renameCategory" },
						{ "cat", cat }, { "name", e.value("name", std::string("")) } };
					const auto res = json::parse(FollowerDeck::Apply(cmd.dump(-1, ' ', false, nlohmann::json::error_handler_t::replace)), nullptr, false);
					if (!res.is_discarded() && res.value("ok", false)) {
						++applied;
						logger::info("portal fo rename: slot {} -> '{}'", cat, e.value("name", std::string("")));
					} else {
						++skipped;
						logger::info("portal fo rename slot {} skipped: {}", cat,
							res.is_discarded() ? std::string("bad reply") : res.value("msg", std::string("?")));
					}
				} else {
					++skipped;  // unknown op type
				}
			}
			if (applied || skipped)
				logger::info("portal fo-ops: {} applied, {} skipped", applied, skipped);
		}

		// Consume it either way — a file we could not apply must not be retried
		// forever. Same delete-or-blank fallback as ApplyPortalNpcFields().
		std::filesystem::remove(file, ec);
		if (ec) {
			logger::warn("could not delete portal fo-ops ({}) — blanking instead", ec.message());
			std::ofstream out(file, std::ios::binary | std::ios::trunc);
			if (out.is_open())
				out << R"({"version":1,"ops":[]})";
		}
		return applied > 0;
	}

	// --------------------------------------- Deck Portal hotkey-icon handoff
	// Exactly the ApplyPortalAssignments contract, for Config.entries[].icon:
	//
	//   { "version": 1,
	//     "assign": [ { "entryId": "<Config.entries[].id>",
	//                   "icon": "icons/custom/foo.png" } ] }
	//
	// Lives in the DECK view's icons/custom/ (each view loads icons from its own
	// tree). "" clears the icon. Unknown entryIds are skipped — the player deleted
	// the hotkey — and a malformed file is logged and discarded rather than
	// retried forever. Returns true only when an icon actually changed, so the
	// poller re-pushes the view on real news only.
	bool ApplyPortalHotkeyIcons(const std::filesystem::path& customDir)
	{
		const auto      file = customDir / "portal-hotkey-icons.json";
		std::error_code ec;
		if (!std::filesystem::exists(file, ec))
			return false;

		std::string text;
		{
			std::ifstream in(file, std::ios::binary);
			if (!in.is_open()) {
				// Held open by the portal mid-write: leave it, the next tick gets it.
				logger::warn("portal hotkey icons present but unreadable — retrying");
				return false;
			}
			text.assign((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
		}

		const auto j = json::parse(text, nullptr, false);
		bool       changed = false;
		if (j.is_discarded() || !j.is_object() || !j.contains("assign") || !j["assign"].is_array()) {
			logger::error("portal hotkey icons file is malformed — discarding it");
		} else {
			// Scope the lock TIGHTLY: PersistAll() takes g_configMutex itself and
			// std::mutex is not recursive, so it must be called unlocked.
			std::lock_guard l(g_configMutex);
			for (const auto& e : j["assign"]) {
				if (!e.is_object())
					continue;
				const auto  id = e.value("entryId", std::string(""));
				std::string icon = e.value("icon", std::string(""));
				if (id.empty())
					continue;
				if (!ValidViewIconPath(icon)) {
					logger::warn("portal hotkey icon '{}' is not a view-relative icons/ path — skipped", icon);
					continue;
				}
				// Ids SHOULD be unique, but a hand-edited hotkeys.json can duplicate one;
				// hit every match so a duplicated entry can't disagree with itself.
				bool found = false;
				for (auto& h : g_config.entries) {
					if (h.id != id)
						continue;
					found = true;
					if (h.icon == icon)
						continue;  // already there; don't churn the config file
					logger::info("portal hotkey icon: '{}' -> '{}'", h.name,
						icon.empty() ? std::string("(none)") : icon);
					h.icon = icon;
					changed = true;
				}
				if (!found) {
					logger::info("portal hotkey icon for unknown entry id '{}' — skipped", id);
					continue;
				}
			}
		}

		// Consume it either way — a file we could not apply must not be retried
		// forever. If the delete is refused, blank it so the portal stops showing
		// the change as still pending.
		std::filesystem::remove(file, ec);
		if (ec) {
			logger::warn("could not delete portal hotkey icons ({}) — blanking instead", ec.message());
			std::ofstream out(file, std::ios::binary | std::ios::trunc);
			if (out.is_open())
				out << R"({"version":1,"assign":[]})";
		}
		if (changed && !PersistAll())
			logger::error("portal hotkey icons applied in memory but the config write failed");
		return changed;
	}

	// --------------------------------------- Deck Portal hotkey-edit handoff
	// The fourth sidecar, and the only one that changes what a hotkey IS:
	//
	//   { "version": 1,
	//     "ops": [ { "op": "update", "entryId": "<Config.entries[].id>",
	//                "name": "...", "desc": "...", "category": "...",
	//                "device": "keyboard"|"mouse", "code": 65, "label": "F7",
	//                "mods": [42, 29] },
	//              { "op": "delete", "entryId": "..." } ] }
	//
	// PARTIAL by design: only the keys PRESENT are touched, so the phone can push a
	// rename without shipping (and re-staling) the rest of the entry. An empty
	// desc/category IS a value — it clears the field; the writer omits what it does
	// not mean to change. A phone cannot "press a key to bind", so a rebind arrives
	// as device + code + label (+ mods) from the portal's curated DIK table.
	//
	// Same mechanics as the other three sidecars: dedupe by entryId (last update
	// wins; a delete always beats an update for the same id, whichever order they
	// arrived in), the CONSUMER deletes the file, an unreadable file (the portal
	// mid-write) is left for the next tick, a malformed one is discarded rather
	// than retried forever, and an unknown entryId is logged and skipped.
	// Config-only, so it is safe on the poller thread and at the main menu.

	constexpr std::size_t kPortalNameMax  = 64;   // an entry must keep a usable name
	constexpr std::size_t kPortalDescMax  = 200;
	constexpr std::size_t kPortalLabelMax = 24;   // the deck prints it verbatim on the key cap
	constexpr std::size_t kPortalModsMax  = 3;    // Shift/Ctrl/Alt is the whole vocabulary

	// Trim ASCII whitespace off both ends. Deliberately not std::isspace: that is
	// locale-dependent and UB on a negative char (UTF-8 bytes are negative).
	std::string PortalTrim(std::string s)
	{
		const auto ws = [](char c) {
			return c == ' ' || c == '\t' || c == '\r' || c == '\n';
		};
		std::size_t b = 0, e = s.size();
		while (b < e && ws(s[b]))
			++b;
		while (e > b && ws(s[e - 1]))
			--e;
		return s.substr(b, e - b);
	}

	// Trim, then cap the BYTE length without ever splitting a UTF-8 sequence:
	// ConfigToJson(...).dump(-1, ' ', false, nlohmann::json::error_handler_t::replace) throws on invalid UTF-8 and OpenPalette() calls it
	// unguarded, so half a character here would be a CTD, not a cosmetic bug.
	// (json::parse already guarantees the input string is valid UTF-8.)
	std::string PortalTrimCap(std::string s, std::size_t maxBytes)
	{
		s = PortalTrim(std::move(s));
		if (s.size() > maxBytes) {
			std::size_t n = maxBytes;
			while (n > 0 && (static_cast<unsigned char>(s[n]) & 0xC0) == 0x80)
				--n;  // back off the continuation bytes onto a lead byte
			s.resize(n);
		}
		return s;
	}

	// One collapsed queue slot: the phone may have tapped several times on one
	// entry before the game got a tick.
	struct PendingHotkeyEdit
	{
		std::string id;
		bool        del = false;
		json        fields;  // the winning "update" op; unused when del
	};

	// Apply one "update" op to one entry. THE CALLER HOLDS g_configMutex (the
	// category whitelist lives in g_config). Every field is validated on its own:
	// a bad one is logged and dropped and the rest of the op still lands — a phone
	// that sends one out-of-range code must not also lose the rename it sent with
	// it. Returns true when the entry really changed.
	bool ApplyOneHotkeyEdit(HotkeyEntry& h, const json& e)
	{
		bool changed = false;

		// --- name: an entry must always keep a name, so an empty one is ignored.
		if (e.contains("name")) {
			if (!e["name"].is_string()) {
				logger::warn("portal hotkey edit '{}': name is not a string — skipped", h.name);
			} else {
				const auto name = PortalTrimCap(e["name"].get<std::string>(), kPortalNameMax);
				if (name.empty()) {
					logger::warn("portal hotkey edit '{}': empty name ignored", h.name);
				} else if (name != h.name) {
					logger::info("portal hotkey edit: '{}' renamed -> '{}'", h.name, name);
					h.name = name;
					changed = true;
				}
			}
		}

		// --- desc: "" is a real value (clear the description).
		if (e.contains("desc")) {
			if (!e["desc"].is_string()) {
				logger::warn("portal hotkey edit '{}': desc is not a string — skipped", h.name);
			} else {
				const auto desc = PortalTrimCap(e["desc"].get<std::string>(), kPortalDescMax);
				if (desc != h.desc) {
					logger::info("portal hotkey edit: '{}' desc -> '{}'", h.name,
						desc.empty() ? std::string("(none)") : desc);
					h.desc = desc;
					changed = true;
				}
			}
		}

		// --- category: must already be a tab (case-sensitive); "" = All only. The
		// portal never creates tabs — that is a deck edit, and inventing one here
		// would resurrect a tab the player just deleted.
		if (e.contains("category")) {
			if (!e["category"].is_string()) {
				logger::warn("portal hotkey edit '{}': category is not a string — skipped", h.name);
			} else {
				const auto cat = PortalTrim(e["category"].get<std::string>());  // NOT capped: it must match a tab byte for byte
				const bool known = cat.empty() ||
					std::find(g_config.categories.begin(), g_config.categories.end(), cat) != g_config.categories.end();
				if (!known) {
					logger::warn("portal hotkey edit '{}': unknown category '{}' — skipped (add the tab in-game first)",
						h.name, cat);
				} else if (cat != h.category) {
					logger::info("portal hotkey edit: '{}' category -> '{}'", h.name,
						cat.empty() ? std::string("(All only)") : cat);
					h.category = cat;
					changed = true;
				}
			}
		}

		// --- the binding: device / code / label / mods.
		const bool hasDevice = e.contains("device");
		const bool hasCode = e.contains("code");
		const bool hasLabel = e.contains("label");
		const bool hasMods = e.contains("mods");
		if (!hasDevice && !hasCode && !hasLabel && !hasMods)
			return changed;

		// The action verb is C++-owned: an action entry can be renamed and re-filed
		// from the phone, never re-bound, and a key entry can never be turned INTO
		// one. Both directions would produce an entry OnJsFire cannot dispatch.
		// Same for vkey and console entries: their payload lives in code/command,
		// not a scancode, so a portal "rebind" would strand them on a device
		// whose fire path ignores what they actually do.
		if (h.device == "action" || h.device == "vkey" || h.device == "console") {
			logger::warn("portal hotkey edit '{}': {} entry — binding fields skipped", h.name, h.device);
			return changed;
		}

		std::string device = h.device;
		if (hasDevice) {
			if (!e["device"].is_string()) {
				logger::warn("portal hotkey edit '{}': device is not a string — skipped", h.name);
			} else {
				const auto d = PortalTrim(e["device"].get<std::string>());
				if (!ValidDevice(d))  // rejects "action" too, by construction
					logger::warn("portal hotkey edit '{}': device '{}' is not keyboard/mouse — skipped", h.name, d);
				else
					device = d;
			}
		}

		// Range depends on the device the entry ENDS UP on: keyboard = DIK scancode,
		// mouse = Skyrim idCode (2 middle / 3 Mouse4 / 4 Mouse5).
		const auto inRange = [](const std::string& dev, std::uint32_t c) {
			return dev == "mouse" ? (c >= 2 && c <= 4) : (c >= 1 && c <= 255);
		};

		std::uint32_t code = h.code;
		bool          rebind = false;
		bool          codeRejected = false;
		if (hasCode) {
			if (!e["code"].is_number_integer()) {
				logger::warn("portal hotkey edit '{}': code is not a number — skipped", h.name);
				codeRejected = true;
			} else {
				const auto raw = e["code"].get<std::int64_t>();
				if (raw < 0 || raw > 255 || !inRange(device, static_cast<std::uint32_t>(raw))) {
					logger::warn("portal hotkey edit '{}': code {} is out of range for device '{}' — binding skipped",
						h.name, raw, device);
					codeRejected = true;
				} else {
					code = static_cast<std::uint32_t>(raw);
					rebind = true;
				}
			}
		} else if (device != h.device && !inRange(device, h.code)) {
			// Device switched with no new code, and the old code cannot live there
			// (e.g. keyboard 65 -> mouse). Refuse rather than leave a dead entry.
			logger::warn("portal hotkey edit '{}': device '{}' needs a code that fits it — skipped", h.name, device);
			codeRejected = true;
		}
		if (codeRejected)
			device = h.device;  // never strand an entry on a device its code cannot fire

		if (device != h.device) {
			logger::info("portal hotkey edit: '{}' device -> '{}'", h.name, device);
			h.device = device;
			changed = true;
		}
		if (rebind && code != h.code) {
			logger::info("portal hotkey edit: '{}' code -> {}", h.name, code);
			h.code = code;
			changed = true;
		}

		// Cosmetic, and the deck prints it verbatim — so it may travel alone, but
		// never alongside a code we just refused (that would label the key a lie).
		if (hasLabel && !codeRejected) {
			if (!e["label"].is_string()) {
				logger::warn("portal hotkey edit '{}': label is not a string — skipped", h.name);
			} else {
				const auto label = PortalTrimCap(e["label"].get<std::string>(), kPortalLabelMax);
				if (label != h.label) {
					logger::info("portal hotkey edit: '{}' label -> '{}'", h.name,
						label.empty() ? std::string("(none)") : label);
					h.label = label;
					changed = true;
				}
			}
		}

		// An explicit [] clears the chord; same "not with a refused code" rule.
		if (hasMods && !codeRejected) {
			if (!e["mods"].is_array()) {
				logger::warn("portal hotkey edit '{}': mods is not an array — skipped", h.name);
			} else {
				std::vector<std::uint32_t> mods;
				std::size_t                bad = 0, over = 0;
				for (const auto& m : e["mods"]) {
					if (!m.is_number_integer()) {
						++bad;
						continue;
					}
					const auto raw = m.get<std::int64_t>();
					if (raw < 1 || raw > 255) {
						++bad;
						continue;
					}
					const auto v = static_cast<std::uint32_t>(raw);
					if (std::find(mods.begin(), mods.end(), v) != mods.end())
						continue;  // deduped: holding a key twice is still holding it once
					if (mods.size() >= kPortalModsMax) {
						++over;
						continue;
					}
					mods.push_back(v);
				}
				if (bad || over)
					logger::warn("portal hotkey edit '{}': {} bad modifier(s), {} past the {}-modifier limit — dropped",
						h.name, bad, over, kPortalModsMax);
				if (mods != h.mods) {
					logger::info("portal hotkey edit: '{}' mods -> {} held key(s)", h.name, mods.size());
					h.mods = std::move(mods);
					changed = true;
				}
			}
		}
		return changed;
	}

	// Returns true only when the config really changed — the poller's "worth
	// repainting the deck" signal.
	bool ApplyPortalHotkeyEdits(const std::filesystem::path& deckDir)
	{
		const auto      file = deckDir / "portal-hotkey-edits.json";
		std::error_code ec;
		if (!std::filesystem::exists(file, ec))
			return false;

		std::string text;
		{
			std::ifstream in(file, std::ios::binary);
			if (!in.is_open()) {
				// Held open by the portal mid-write: leave it, the next tick gets it.
				logger::warn("portal hotkey edits present but unreadable — retrying");
				return false;
			}
			text.assign((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
		}

		const auto j = json::parse(text, nullptr, false);
		bool       changed = false;
		if (j.is_discarded() || !j.is_object() || !j.contains("ops") || !j["ops"].is_array()) {
			logger::error("portal hotkey edits file is malformed — discarding it");
		} else {
			// Pass 1, no lock: collapse the queue in arrival order.
			std::vector<PendingHotkeyEdit> queue;
			for (const auto& e : j["ops"]) {
				if (!e.is_object())
					continue;
				if (!e.contains("entryId") || !e["entryId"].is_string())
					continue;
				const auto id = e["entryId"].get<std::string>();
				if (id.empty())
					continue;
				std::string op = "update";  // a missing op is an update
				if (e.contains("op")) {
					if (!e["op"].is_string()) {
						logger::warn("portal hotkey edit for '{}': op is not a string — skipped", id);
						continue;
					}
					op = e["op"].get<std::string>();
				}
				if (op != "update" && op != "delete") {
					logger::warn("portal hotkey edit for '{}': unknown op '{}' — skipped", id, op);
					continue;
				}
				auto it = std::find_if(queue.begin(), queue.end(),
					[&id](const PendingHotkeyEdit& p) { return p.id == id; });
				if (it == queue.end()) {
					PendingHotkeyEdit p;
					p.id = id;
					p.del = (op == "delete");
					if (!p.del)
						p.fields = e;
					queue.push_back(std::move(p));
				} else if (op == "delete") {
					it->del = true;  // a delete always wins, whatever the order
				} else if (!it->del) {
					it->fields = e;  // last update wins
				}
			}

			std::size_t updated = 0, removed = 0, unknown = 0;
			{
				// Scope the lock TIGHTLY: PersistAll() takes g_configMutex itself and
				// std::mutex is not recursive, so it must be called unlocked.
				std::lock_guard l(g_configMutex);
				for (const auto& p : queue) {
					if (p.del) {
						const auto before = g_config.entries.size();
						g_config.entries.erase(
							std::remove_if(g_config.entries.begin(), g_config.entries.end(),
								[&p](const HotkeyEntry& h) { return h.id == p.id; }),
							g_config.entries.end());
						const auto gone = before - g_config.entries.size();
						if (gone == 0) {
							++unknown;
							logger::info("portal hotkey delete for unknown entry id '{}' — skipped", p.id);
							continue;
						}
						// Deleting the LAST entry is allowed; the deck draws an empty state.
						removed += gone;
						changed = true;
						logger::info("portal hotkey delete: id '{}' ({} removed, {} entries left)",
							p.id, gone, g_config.entries.size());
						continue;
					}
					// Ids SHOULD be unique, but a hand-edited hotkeys.json can duplicate
					// one; hit every match so a duplicate can't disagree with itself.
					bool found = false;
					for (auto& h : g_config.entries) {
						if (h.id != p.id)
							continue;
						found = true;
						if (ApplyOneHotkeyEdit(h, p.fields)) {
							++updated;
							changed = true;
						}
					}
					if (!found) {
						++unknown;
						logger::info("portal hotkey edit for unknown entry id '{}' — skipped", p.id);
					}
				}
			}
			if (updated || removed || unknown)
				logger::info("portal hotkey edits: {} updated, {} deleted, {} unknown", updated, removed, unknown);
		}

		// Consume it either way — a file we could not apply must not be retried
		// forever. If the delete is refused, blank it so the portal stops showing
		// the change as still pending.
		std::filesystem::remove(file, ec);
		if (ec) {
			logger::warn("could not delete portal hotkey edits ({}) — blanking instead", ec.message());
			std::ofstream out(file, std::ios::binary | std::ios::trunc);
			if (out.is_open())
				out << R"({"version":1,"ops":[]})";
		}
		if (changed && !PersistAll())
			logger::error("portal hotkey edits applied in memory but the config write failed");
		return changed;
	}

	// fdApply: an in-place mutation (rename / note / move / reorder / delete /
	// add / track / category ops). Every reply re-renders the pane from the
	// fresh state the envelope carries.
	void OnJsFolApply(const char* data)
	{
		const std::string cmd = data ? data : "";
		SKSE::GetTaskInterface()->AddTask([cmd]() {
			PushToView("fdState", FollowerDeck::Apply(cmd));
			// A recruit/track/add can change WHO is following, so refresh the live
			// party alongside the roster (main thread — HudFollowersJson scans
			// actors). Cheap and keeps the Current-party bar honest after a mutate.
			PushToView("fdLiveParty", HudFollowersJson());
		});
	}

	// fdWorld: summon / goto / sendback — physical, not administrative. Close
	// the palette first so the teleport lands in the live world, then run, then
	// optionally reopen (closeAfterFire=false), same shape as spell casts.
	// Photograph the follower you clicked, rather than whatever the crosshair
	// happened to be on when the palette opened. Same capture pipeline as the
	// CHIM tab's action — it just names its subject.
	//
	// The palette closes first for the same reason the action does: it is a
	// full-screen web view, and a portrait of it is not a portrait of her.
	void OnJsFolPortrait(const char* data)
	{
		if (!data)
			return;
		const auto j = json::parse(data, nullptr, false);
		if (j.is_discarded() || !j.is_object()) {
			logger::warn("fdPortrait: bad payload");
			return;
		}
		// The view sends the FO form string ("0x00a2c8"); accept a number too so
		// a future caller does not have to care.
		std::uint32_t formId = 0;
		if (const auto it = j.find("formId"); it != j.end()) {
			if (it->is_number_unsigned()) {
				formId = it->get<std::uint32_t>();
			} else if (it->is_string()) {
				const auto s = it->get<std::string>();
				formId = static_cast<std::uint32_t>(std::strtoul(s.c_str(), nullptr, 16));
			}
		}
		if (!formId) {
			logger::warn("fdPortrait: no usable formId in {}", j.dump(-1, ' ', false, nlohmann::json::error_handler_t::replace));
			return;
		}
        const auto requestId = j.value("requestId", std::string{});
        const auto settings = j.contains("framing") ? j["framing"] : json();
        const auto lighting = j.contains("lighting") ? j["lighting"] : json();
        const auto dir = DeckViewDir() / "portraits";
        SKSE::GetTaskInterface()->AddTask([dir, formId, settings, lighting, requestId]() {
            auto reply = [&requestId](bool ok, const char* message) {
                if (!requestId.empty()) PushToView("fdCaptureSetupResult",
                    json{{"requestId",requestId},{"ok",ok},{"message",message}}.dump());
            };
            auto* actor = RE::TESForm::LookupByID<RE::Actor>(formId);
            if (!actor || !actor->Get3D()) { reply(false,"Bring this NPC into view before starting a portrait."); return; }
            if (PortraitCapture::PhotoModeActive() || PortraitCapture::SelfCaptureBusy()) { reply(false,"Finish the current photograph first."); return; }
            auto light = PortraitCapture::GetNpcLighting(dir);
            if (!lighting.is_null() && (!lighting.is_object() || !lighting.contains("mode") ||
                !lighting["mode"].is_string() || !lighting.contains("strength") || !lighting["strength"].is_number() ||
                !PhotoLighting::Parse(lighting["mode"].get<std::string>(),lighting["strength"].get<float>(),light))) {
                reply(false,"Invalid portrait lighting settings."); return;
            }
            if (!settings.is_null()) {
                if (!settings.is_object()) {reply(false,"Invalid capture settings.");return;}
                for (const char* key : {"zoom","offsetX","offsetY"}) {
                    if (!settings.contains(key) || !settings[key].is_number()) {reply(false,"Invalid capture settings.");return;}
                    const double value = settings[key].get<double>();
                    const bool zoom = std::string_view(key) == "zoom";
                    if (!std::isfinite(value) || value < (zoom ? 0.15 : -0.5) || value > (zoom ? 1.0 : 0.5)) {
                        reply(false,"Capture settings are out of range.");return;
                    }
                }
                PortraitCapture::Framing f;
                f.zoom=settings["zoom"].get<float>();f.offsetX=settings["offsetX"].get<float>();f.offsetY=settings["offsetY"].get<float>();
                if (!PortraitCapture::SetFraming(dir,f)) {reply(false,"Could not save capture settings. No photograph taken.");return;}
                logger::info("portrait-retake-setup: confirmed capture settings for {:08X}",formId);
            }
            if (!lighting.is_null() && !PortraitCapture::SetNpcLighting(dir,light)) { reply(false,"Could not save face-light settings. No photograph taken."); return; }
            if (!PortraitCapture::ArmNpcPortrait(dir, formId)) { reply(false,"Could not start portrait lighting. Keep the NPC nearby and try again."); return; }
            reply(true,"Portrait armed - frame the NPC, then press Enter. Esc or your SkyManager key returns.");
            // ARM, don't fire (Rober, 2026-09-23: "the retake photo for npcs should
            // wait for me to press e"). The palette closes, he frames her, and the
            // next Enter takes it; Esc or the deck key cancels. See ArmNpcPortrait.
            PreparePhotoReturn();
            ClosePalette();
        });
	}

	void OnJsFolWorld(const char* data)
	{
		const std::string cmd = data ? data : "{}";
		const auto j = json::parse(cmd, nullptr, false);
		if (!j.is_object()) return;
		const auto label = j.value("label", std::string());
		SKSE::GetTaskInterface()->AddTask([cmd, label]() {
			QueueTravel("Followers", [cmd, label]() {
				const auto jr = json::parse(FollowerDeck::Apply(cmd), nullptr, false);
				const bool ok = jr.is_object() && jr.value("ok", false);
				auto msg = jr.is_object() ? jr.value("msg", std::string()) : std::string();
				if (!ok && msg.empty()) msg = "Follower action failed - see HotkeyDeck.log";
				if (msg.empty()) msg = label;
				if (!msg.empty()) RE::DebugNotification(msg.c_str());
			});
		});
	}

	// The NFF / My Home is Your Home snapshot goes out in TWO directions, and
	// both want the same freshly built payload: the in-game pane gets it as
	// `fdNff`, and the Deck Portal gets the MHiYH half of it re-keyed by
	// original name in mhiyh-status.json (a phone has no runtime FormIDs —
	// see the header of src/mhiyh_control.h). One helper, so the export can
	// never be forgotten at one of the four places that push the state.
	/* ---- the LIVE roster, for the phone ---------------------------------
	 *  "deleting in game didnt delete them from the web-app" (Rober).
	 *
	 *  Not a portal bug. The portal reads FollowerOrganizer.json off disk, and
	 *  Follower Organizer holds the whole roster IN MEMORY while the game runs
	 *  — it rewrites the file on its own schedule. So the phone was showing a
	 *  snapshot from some earlier moment and had no way to know it was stale.
	 *  The same law that stops the portal WRITING that file (it would be
	 *  discarded) also stops it trusting the file for reads.
	 *
	 *  So export what the deck already has in hand. FollowerDeck::StateJson()
	 *  is FO's own live state, straight from the singleton — the very payload
	 *  the Followers tab renders — and this is the one place every refresh
	 *  funnels through, so the export cannot drift from what the deck shows.
	 *  Stamped with `at` so the portal can prefer whichever source is FRESHER
	 *  rather than guessing.
	 */
	void WriteRosterExport(const std::string& fo)
	{
		auto state = json::parse(fo, nullptr, false);
		if (state.is_discarded() || !state.is_object())
			return;   // nothing worth writing; keep the last good export

		const auto now = std::chrono::duration_cast<std::chrono::milliseconds>(
			std::chrono::system_clock::now().time_since_epoch()).count();
		state["at"] = static_cast<long long>(now);
		state["source"] = "live";

		const auto dir = DeckViewDir();
		std::error_code ec;
		std::filesystem::create_directories(dir, ec);
		const auto file = dir / "fo-roster.json";
		const auto tmp = dir / "fo-roster.json.tmp";
		{
			std::ofstream out(tmp, std::ios::binary | std::ios::trunc);
			if (!out.is_open())
				return;
			out << state.dump(-1, ' ', false, json::error_handler_t::replace);
		}
		std::filesystem::rename(tmp, file, ec);   // atomic: never a half file
		if (ec)
			return;

		static bool said = false;
		if (!said) {
			said = true;
			logger::info("fo: live roster exported for the portal");
		}
	}

	void PushFollowerNff(const std::string& fo)
	{
		const auto nff = NffBridge::StateJson(fo);
		PushToView("fdNff", nff);
		MhiyhControl::WriteStatusJson(DeckViewDir(), fo, nff);
		WriteRosterExport(fo);
	}

	// What a PHONE-queued day change does when MHiYH finally answers. Byte for
	// byte what an in-deck click does (see OnJsFolMhiyh below): the open pane
	// gets the same `fdMhiyhResult` toast and the same repaint, so a change made
	// from the phone is indistinguishable from one made in game. Main thread —
	// MhiyhControl hops for us before calling this.
	void PortalMhiyhDone(const std::string& res)
	{
		PushToView("fdMhiyhResult", res);
		PushFollowerNff(FollowerDeck::StateJson());
	}

	// fdMhiyh: tell My Home is Your Home NG to change someone's day — give or
	// move a home, mark or clear one of the six other stops, forget the lot.
	//
	// NAMING: request listener `fdMhiyh`, reply pushed as `fdMhiyhResult` — the
	// two MUST differ. PrismaUI installs every registered listener as a JS
	// global of its own name, so a pane that also assigns `window.fdMhiyh` to
	// catch the reply overwrites the bridge, and `toGame('fdMhiyh')` then calls
	// the pane's own handler instead of this function. That is not a cosmetic
	// clash: it silently unplugs the whole feature (proven on fdNpc/fdEquipped
	// in v0.10, and this listener carried the same defect until 2026-08-02).
	//
	// Deliberately NOT shaped like fdWorld: nothing here teleports anybody, and
	// the marker every op creates is placed at the PLAYER'S feet, so closing the
	// palette would gain nothing and cost the popout you set it from. Same
	// posture as hdQuestSetStage, which has fired Papyrus from inside the open
	// palette since v0.4.0.
	//
	// TWO replies per op, because the Papyrus call is asynchronous: `phase:
	// "sent"` the moment the stack is queued (or `"refused"` if MhiyhControl
	// turned it down without dispatching), then `phase: "done"` carrying MHiYH's
	// own Bool. The second one also re-pushes fdNff, so the day stepper repaints
	// itself with whatever the mod actually did rather than what we hoped.
	void OnJsFolMhiyh(const char* data)
	{
		const std::string cmd = data ? data : "";
		SKSE::GetTaskInterface()->AddTask([cmd]() {
			const auto pre = MhiyhControl::Apply(cmd, [](const std::string& res) {
				// Already back on the main thread — MhiyhControl hops for us.
				PushToView("fdMhiyhResult", res);
				const auto fo = FollowerDeck::StateJson();
				PushFollowerNff(fo);
			});
			// Early refusals precede actor resolution and used to omit identity.
			// Keep feedback attached to the request, never the current crosshair.
			auto reply = json::parse(pre, nullptr, false);
			const auto request = json::parse(cmd, nullptr, false);
			if (reply.is_object() && !reply.contains("formId") &&
				request.is_object() && request.contains("formId")) {
				reply["formId"] = request["formId"];
				logger::debug("[followers] mhiyh-reply-identity");
				PushToView("fdMhiyhResult", reply.dump(-1, ' ', false, json::error_handler_t::replace));
			} else {
				PushToView("fdMhiyhResult", pre);
			}
		});
	}

	// CHIM button — parse { formId, name } from the view. formId may arrive as a
	// JSON number or a "0x…"/decimal string; be tolerant of both.
	std::uint32_t ChParseFormId(const json& j)
	{
		try {
			if (j.contains("formId")) {
				const auto& v = j.at("formId");
				if (v.is_number_unsigned())
					return v.get<std::uint32_t>();
				if (v.is_number_integer())
					return static_cast<std::uint32_t>(v.get<std::int64_t>());
				if (v.is_string()) {
					const auto s = v.get<std::string>();
					if (!s.empty())
						return static_cast<std::uint32_t>(std::stoul(s, nullptr, 0));
				}
			}
		} catch (...) {}
		return 0;
	}

	// chState: read whether the NPC is currently a CHIM agent -> chStateResult.
	void OnJsChConversation(const char* data)
	{
		const std::string request = data ? data : "{}";
		const auto epoch = g_conversationEpoch.load();
		SKSE::GetTaskInterface()->AddTask([request, epoch]() {
			if (!g_gameReady.load() || epoch != g_conversationEpoch.load()) {
				auto j = json::parse(request, nullptr, false);
				const auto id = j.is_object() && j.contains("requestId") && j["requestId"].is_string() ? j["requestId"].get<std::string>() : "";
				PushToView("chConversationResult", json{{"ok", false}, {"requestId", id}, {"msg", "Load a game and reopen this NPC's card"}}.dump());
				return;
			}
			PushToView("chConversationResult", NpcActions::ConversationControl(request));
		});
	}

	void OnJsChState(const char* data)
	{
		const std::string in = data ? data : "";
		SKSE::GetTaskInterface()->AddTask([in]() {
			std::uint32_t fid = 0;
			std::string   name;
			try {
				const auto j = json::parse(in);
				fid = ChParseFormId(j);
				name = j.value("name", "");
			} catch (...) {}
			ChimControl::QueryActive(fid, name, [fid, name](bool active, bool ok) {
				PushToView("chStateResult",
					json{ { "formId", fid }, { "name", name },
						{ "active", active }, { "ok", ok } }
						.dump(-1, ' ', false, nlohmann::json::error_handler_t::replace));
			});
		});
	}

	// chSet: activate/deactivate CHIM AI, then reconcile the label from the
	// mod's own agent set. The optimistic push makes the button feel instant;
	// the reconcile push corrects it if the toggle was refused.
	void OnJsChSet(const char* data)
	{
		const std::string in = data ? data : "";
		SKSE::GetTaskInterface()->AddTask([in]() {
			std::uint32_t fid = 0;
			std::string   name;
			bool          on = true;
			try {
				const auto j = json::parse(in);
				fid = ChParseFormId(j);
				name = j.value("name", "");
				on = j.value("on", true);
			} catch (...) {}
			const bool sent = ChimControl::SetActive(fid, name, on);
			// Optimistic: if we dispatched, assume the requested state.
			PushToView("chStateResult",
				json{ { "formId", fid }, { "name", name },
					{ "active", sent ? on : false }, { "ok", sent } }
					.dump(-1, ' ', false, nlohmann::json::error_handler_t::replace));
			// Reconcile from CHIM's own agent set (getAgentByName).
			ChimControl::QueryActive(fid, name, [fid, name](bool active, bool ok) {
				if (!ok)
					return;   // keep the optimistic value
				PushToView("chStateResult",
					json{ { "formId", fid }, { "name", name },
						{ "active", active }, { "ok", true } }
						.dump(-1, ' ', false, nlohmann::json::error_handler_t::replace));
			});
		});
	}

	// fmAll: every actor Fertility Mode tracks -> fmAllResult (see
	// FertilityBridge::AllTrackedJson). A synchronous property read, no
	// Papyrus dispatch — same posture as the per-roster fdFertility push.
	void OnJsFmAll(const char*)
	{
		SKSE::GetTaskInterface()->AddTask([]() {
			PushToView("fmAllResult", FertilityBridge::AllTrackedJson());
		});
	}

	// chAgents: every CHIM agent right now -> chAgentsResult
	//   { ok, agents: [{ formId, name, base }] }
	// The view (chim-flyout.js) keys its "is she activated" answer on formId
	// OR either name, so a renamed follower still matches her roster row.
	void OnJsChAgents(const char*)
	{
		SKSE::GetTaskInterface()->AddTask([]() {
			ChimControl::QueryAgents([](const std::vector<ChimControl::Agent>& agents, bool ok) {
				json list = json::array();
				for (const auto& a : agents) {
					list.push_back(json{ { "formId", a.formId }, { "name", a.name }, { "base", a.base } });
				}
				PushToView("chAgentsResult",
					json{ { "ok", ok }, { "agents", std::move(list) } }
						.dump(-1, ' ', false, nlohmann::json::error_handler_t::replace));
			});
		});
	}

	// fdNpc: quick recruit / dismiss / open-inventory against ONE actor —
	//
	// NAMING: the request listener is `fdNpc`, the reply is pushed as
	// `fdNpcResult`. They MUST differ — PrismaUI installs every registered
	// listener as a JS global of that name, so reusing one name means the
	// view's `toGame('fdNpc', …)` resolves to the view's OWN receiver and the
	// call never reaches C++ at all. Same rule as hdIconList -> hdIcons.
	// either a roster member the pane named, or (with no formId) whoever was
	// under the crosshair when the palette opened.
	//
	// Two phases like fdMhiyh, for the same reason: the Papyrus call is
	// asynchronous, so `phase:"sent"` goes back the moment the stack is queued
	// and `phase:"done"` carries what actually happened. A `phase:"refused"`
	// is final and never gets a second reply.
	//
	// The palette-closing rule differs PER OP, which is why this is not shaped
	// like fdWorld:
	//   * recruit / dismiss — the palette STAYS OPEN (like fdMhiyh). Recruiting
	//     is administrative; closing the deck to do it would cost you the tab
	//     you were working in, and NFF's own notification is the feedback.
	//   * inventory / storage — the palette MUST close first. The ContainerMenu
	//     cannot open while PrismaUI owns input focus, and it does NOT reopen
	//     after: you are now standing in that container, and popping the deck
	//     back over it is exactly the overlap this project treats as a bug.
	//     BOTH container ops, not just the first — see the closing test below.
	// ------------------------------------------------------- Gear Toggle --
	// fdGear: the Followers card's "hide worn gear" toggles, riding Gear
	// Toggle's in-process C API. Both ops BLOCK on the game thread inside the
	// engine, so they leave the deck thread first — worker out, task back in.
	void OnJsFolGear(const char* data)
	{
		if (!data)
			return;
		const auto j = json::parse(data, nullptr, false);
		if (j.is_discarded() || !j.is_object()) {
			logger::warn("fdGear: bad payload");
			return;
		}
		const std::string op = j.value("op", "");
		const std::uint32_t formId = j.value("formId", 0u);
		if (!formId) {
			PushToView("fdGearResult", R"({"ok":false,"error":"no one to hide gear on"})");
			return;
		}
		char hex[16];
		std::snprintf(hex, sizeof(hex), "%08X", formId);

		json body;
		body["formId"] = hex;
		std::string path;
		if (op == "toggle") {
			body["group"] = j.value("group", "");
			path = "/toggle";
			logger::info("gear-toggle: {} {}", hex, body["group"].get<std::string>());
		} else {
			path = "/state";
		}
		std::thread([path, payload = body.dump(-1, ' ', false, nlohmann::json::error_handler_t::replace)]() {
			const std::string res = GearBridge::Call("POST", path, payload);
			if (auto* tasks = SKSE::GetTaskInterface())
				tasks->AddTask([res]() { PushToView("fdGearResult", res); });
		}).detach();
	}

	// ------------------------------------------------------ Preset Director --
	// fdPreset: the Followers tab's preset tools, riding Preset Director's
	// in-process C API (preset_bridge.cpp). GET routes (/presets, /registry)
	// are pure file/memory reads inside PD and safe to call inline; the POST
	// routes (apply/spawn) BLOCK their calling thread on an SKSE task, so they
	// leave the game thread first — worker thread out, task back in — or the
	// palette would deadlock itself into PD's 8s leash.
	std::filesystem::path PresetIconsDir() { return DeckViewDir() / "preset-icons"; }

	// Auto-render batch state — declared ahead of PresetIndexJson, which
	// reports it to the view (live "Rendering k/N" + Stop chip).
	std::atomic<bool> g_presetAutoBusy{ false };
	std::atomic<bool> g_presetAutoCancel{ false };
	std::atomic<int>  g_presetAutoTotal{ 0 };
	std::atomic<int>  g_presetAutoDone{ 0 };
	std::atomic<int>  g_presetAutoFailed{ 0 };
	std::mutex        g_presetAssignLock;

	// Rolling wall-clock cost of one rendered face, so the tab's "N faces ·
	// ≈ M min" line stops being a hardcoded guess. Only SUCCESSFUL renders
	// count — a failure returns in a fraction of the time and would talk the
	// estimate down. Includes our own breather, because that is time the
	// player actually waits. 0 = nothing measured yet; the view keeps its own
	// fallback for that. A short EMA (~last 3), not a running mean: the batch
	// speeds up once one stand-in is serving a whole race run.
	std::atomic<int> g_presetAvgMs{ 0 };

	// Filenames Ultralight has already cached THIS session (a re-render must
	// never reuse one — the view would keep showing the old cached bytes).
	// Declared up here because the self-heal in PresetIndexJson consults it.
	std::set<std::string> g_presetBurnedNames;  // guarded by g_presetAssignLock

	// Presets whose icon the PLAYER cleared by hand (op "img" with icon:"").
	// The orphan self-heal below must never undo that — an image he deleted
	// reappearing on the next repaint reads as the deck fighting him.
	std::set<std::string> g_presetNoAdopt;  // guarded by g_presetAssignLock

	// Presets queued for a forced re-render ("↻ Re-render all"). The redo used
	// to DELETE every auto assignment up front; this set replaces that — see
	// the long note on op "autorender-redo". Guarded by g_presetAssignLock.
	std::set<std::string> g_presetRedoSet;

	// Why a render did not happen, per preset, verbatim from the shape pass or
	// from PD's /thumb reply — reported to the view as index.fails so a
	// failure is visible in the tab instead of only in HotkeyDeck.log
	// (Rober, 2026-08-16: pressed "✨ Render missing (6)", nothing appeared to
	// happen, six presets had been failing identically since the first batch).
	// Cleared for a preset the moment it gets an image. Session-scoped on
	// purpose: it describes THIS run of the game, not a durable property.
	std::map<std::string, std::string> g_presetFails;  // guarded by g_presetAssignLock

	// What the shape pass managed to infer, EVEN WHEN it was not confident —
	// {race, sex, faceEdid, confident}. A preset PD refuses is exactly the one
	// the player needs to answer "render it as which race?" for, and that
	// answer is far easier to give when the tab can pre-fill the guess.
	std::map<std::string, json> g_presetShape;  // guarded by g_presetAssignLock

	// Batch pacing (Rober, 2026-08-16: "the face generation stuff causes some
	// pretty bad lag in general"). Each /thumb spawns a stand-in, runs Papyrus
	// and renders in the LIVE world, so back-to-back calls never let the game
	// catch its breath. These are the deck's own spacing — PD's internal
	// settle timings are its business and are deliberately untouched.
	constexpr int kPresetShapeBreatherMs = 40;   // 120 shape probes = 120 game hops
	constexpr int kPresetRenderBreatherMs = 350;  // ~25% on a ~1.3 s render

	// assign.json is rewritten by the auto-render worker while the index (game
	// thread / JS-listener thread) reads it — every access goes through
	// g_presetAssignLock or a torn read paints an icon-less gallery.
	json PresetAssignmentsUnlocked()
	{
		json          m = json::object();
		std::ifstream in(PresetIconsDir() / "assign.json");
		if (in) {
			json j = json::parse(in, nullptr, false);
			if (!j.is_discarded() && j.is_object())
				m = std::move(j);
		}
		return m;
	}

	json PresetAssignments()
	{
		std::lock_guard lock(g_presetAssignLock);
		return PresetAssignmentsUnlocked();
	}

	// ATOMIC write — temp file + rename, the deck's config-write idiom.
	// A plain truncate+write leaves a window in which assign.json is empty or
	// half a document, and this map is the ONLY thing tying 200-odd renders to
	// their presets: lose it and every tile goes blank while the PNGs sit
	// uselessly on disk. Caller holds g_presetAssignLock.
	void WritePresetAssignmentsUnlocked(const json& m)
	{
		std::error_code ec;
		const auto      dir = PresetIconsDir();
		std::filesystem::create_directories(dir, ec);
		const auto dst = dir / "assign.json";
		const auto tmp = dir / "assign.json.tmp";
		{
			std::ofstream outF(tmp, std::ios::trunc);
			if (!outF) {
				logger::error("faces: assign.json NOT saved — can't open the temp file");
				return;
			}
			outF << m.dump(2);
			outF.flush();
			if (!outF) {
				logger::error("faces: assign.json NOT saved — the temp write failed");
				return;
			}
		}
		// MoveFileEx-with-replace on Windows: the reader sees the old complete
		// document or the new one, never a truncated one. NEVER remove dst
		// first — that is the exact window this function exists to close.
		std::filesystem::rename(tmp, dst, ec);
		if (ec) {
			logger::error("faces: assign.json rename failed ({}) — writing in place instead", ec.message());
			std::ofstream outF(dst, std::ios::trunc);
			if (outF)
				outF << m.dump(2);
			std::error_code ec2;
			std::filesystem::remove(tmp, ec2);
		}
	}

	// Filename stem for a preset's auto render. Declared before the self-heal,
	// which reads the same naming law it writes.
	std::string PresetAutoStem(const std::string& preset)
	{
		std::string s = "auto-" + preset;
		for (auto& c : s)
			if (c == '<' || c == '>' || c == ':' || c == '"' || c == '/' || c == '\\' ||
				c == '|' || c == '?' || c == '*')
				c = '-';
		while (!s.empty() && (s.back() == ' ' || s.back() == '.'))
			s.pop_back();
		return s;
	}

	// Every auto filename this preset could ever have used, newest first.
	// "Newest" is the file's own mtime, NOT the .rN number: a reclaimed name
	// can be reused, so a high N is not a promise of a recent render.
	std::vector<std::string> PresetAutoFilesOnDisk(const std::string& preset,
		const std::set<std::string>& onDisk)
	{
		const std::string stem = PresetAutoStem(preset);
		std::vector<std::pair<std::filesystem::file_time_type, std::string>> found;
		for (int v = 1; v <= 99; ++v) {
			const std::string cand = (v == 1) ? stem + ".png" : stem + ".r" + std::to_string(v) + ".png";
			if (!onDisk.count(cand))
				continue;
			std::error_code ec;
			const auto      when = std::filesystem::last_write_time(PresetIconsDir() / cand, ec);
			found.emplace_back(ec ? std::filesystem::file_time_type{} : when, cand);
		}
		std::stable_sort(found.begin(), found.end(),
			[](const auto& a, const auto& b) { return a.first > b.first; });
		std::vector<std::string> out;
		for (auto& f : found)
			out.push_back(std::move(f.second));
		return out;
	}

	// SELF-HEAL: re-adopt renders whose mapping was lost.
	//
	// 2026-08-16 play-test: 234 auto-*.png on disk, TEN entries in assign.json.
	// The destructive redo (since fixed below) dropped 114 good mappings and a
	// cancel meant they never came back, while std::filesystem::remove could
	// not actually delete the files (Ultralight memory-maps every image it has
	// drawn and holds it for the session, so the delete fails with a sharing
	// violation and the error_code was swallowed). The renders were all still
	// there; nothing was willing to claim them. So: any preset with no
	// assignment whose auto file exists gets it back, newest render wins.
	// Cheap — it reuses the directory listing PresetIndexJson already builds.
	void PresetAdoptOrphanRenders(const std::vector<std::string>& presetNames,
		const std::set<std::string>&                              onDisk)
	{
		std::lock_guard lock(g_presetAssignLock);
		json            m = PresetAssignmentsUnlocked();
		int             adopted = 0;
		for (const auto& preset : presetNames) {
			if (preset.rfind("PD_", 0) == 0)  // our own face backups, never tiles
				continue;
			if (m.contains(preset) || g_presetNoAdopt.count(preset))
				continue;
			for (const auto& cand : PresetAutoFilesOnDisk(preset, onDisk)) {
				if (g_presetBurnedNames.count(cand))
					continue;  // stale bytes: Ultralight would paint the OLD face
				m[preset] = cand;
				g_presetFails.erase(preset);
				++adopted;
				break;
			}
		}
		if (adopted) {
			WritePresetAssignmentsUnlocked(m);
			logger::info("faces: self-heal adopted {} orphan render(s) into assign.json", adopted);
		}
	}

	// Favorites + categories for the Faces tab. One file beside assign.json:
	// { "fav":[names], "cats":[names], "catOf":{preset:cat} }. PrismaUI can't
	// write, so C++ owns it — same pattern as assign.json.
	std::filesystem::path PresetMetaPath() { return PresetIconsDir() / "meta.json"; }

	json PresetMeta()
	{
		json m;
		std::ifstream in(PresetMetaPath());
		if (in) {
			json j = json::parse(in, nullptr, false);
			if (!j.is_discarded() && j.is_object())
				m = std::move(j);
		}
		if (!m.contains("fav") || !m["fav"].is_array())
			m["fav"] = json::array();
		if (!m.contains("cats") || !m["cats"].is_array())
			m["cats"] = json::array();
		if (!m.contains("catOf") || !m["catOf"].is_object())
			m["catOf"] = json::object();
		// Presets the player has taken OUT of the tab (Rober, 2026-08-15: "ability
		// to remove individual wigs or faces?"). Nothing on disk is touched — the
		// .jslot stays exactly where it is, this is a curation list — so a hidden
		// preset can always be brought back, and the tab stops burning renders on
		// the ones he will never use (including the race-unknown failures).
		if (!m.contains("hidden") || !m["hidden"].is_array())
			m["hidden"] = json::array();
		return m;
	}

	void WritePresetMeta(const json& m)
	{
		std::error_code ec;
		std::filesystem::create_directories(PresetIconsDir(), ec);
		std::ofstream out(PresetMetaPath(), std::ios::trunc);
		if (out)
			out << m.dump(2);
	}

	// ---- The load order's playable races, for "🎭 Render as…" ----
	// The six presets whose head part never resolves can only be rendered by
	// NAMING their race, and on this load order a hardcoded vanilla ten would
	// send Rober typing a modded race blind. So the deck ships the real list.
	//
	// The identity is the EDITOR ID, because that is exactly what PD's /shape
	// answers with (race->GetFormEditorID()) and what /thumb must resolve the
	// override against — anything else and the two ends would disagree. A race
	// with no editor id is dropped: PD could not look it up, so offering it
	// would be a button that cannot work.
	//
	// Playability is asked via the virtual GetPlayable(), never by reaching
	// into data.flags — the flag holder's type differs between CommonLib forks
	// (stl::enumeration vs REX::EnumSet) and that is a needless build trap.
	//
	// Walked ONCE per session and cached: TESDataHandler's form arrays are
	// fixed after load, and PresetIndexJson runs on every landed face.
	std::mutex  g_presetRaceLock;
	std::string g_presetRaceJson;  // serialized array, "" = not walked yet

	json PresetPlayableRaces()
	{
		{
			std::lock_guard lock(g_presetRaceLock);
			if (!g_presetRaceJson.empty()) {
				json cached = json::parse(g_presetRaceJson, nullptr, false);
				if (!cached.is_discarded())
					return cached;
			}
		}
		auto* dh = RE::TESDataHandler::GetSingleton();
		if (!dh)
			return json::array();  // no save / too early — don't cache a lie
		std::vector<std::pair<std::string, std::string>> rows;  // name, edid
		std::set<std::string>                            seen;
		std::size_t                                      noEdid = 0;
		for (auto* race : dh->GetFormArray<RE::TESRace>()) {
			if (!race || !race->GetPlayable())
				continue;
			const char* ed = race->GetFormEditorID();
			if (!ed || !*ed) {
				++noEdid;
				continue;
			}
			if (!seen.insert(ed).second)
				continue;
			const char* nm = race->GetName();
			rows.emplace_back((nm && *nm) ? nm : ed, ed);
		}
		std::sort(rows.begin(), rows.end());
		json out = json::array();
		for (const auto& [name, edid] : rows)
			out.push_back(json{ { "edid", edid }, { "name", name } });
		logger::info("faces: {} playable race(s) offered for the render-as override ({} skipped, no editor id)",
			out.size(), noEdid);
		{
			std::lock_guard lock(g_presetRaceLock);
			g_presetRaceJson = out.dump(-1, ' ', false, json::error_handler_t::replace);
		}
		return out;
	}

	// Every preset name PD can see, from a parsed /presets reply. Both the
	// index and the batch need this list and they must agree on it.
	std::vector<std::string> PresetCatalogueNames(const json& presets)
	{
		std::set<std::string> names;
		if (!presets.is_discarded() && presets.is_object())
			for (const char* key : { "exported", "presets" })
				for (const auto& p : presets.value(key, json::array()))
					if (p.is_string())
						names.insert(p.get<std::string>());
		return { names.begin(), names.end() };
	}

	std::string PresetIndexJson()
	{
		json out;
		out["ok"] = true;
		out["available"] = PresetBridge::Available();
		json presets = json::parse(PresetBridge::Call("GET", "/presets", ""), nullptr, false);
		json registry = json::parse(PresetBridge::Call("GET", "/registry", ""), nullptr, false);
		out["presets"] = presets.is_discarded() ? json::object() : presets;
		out["registry"] = registry.is_discarded() ? json::object() : registry;
		// Icon files living in the view's own folder (like portraits/), so the
		// tiles are plain relative URLs the webview can already reach.
		json                  icons = json::array();
		std::set<std::string> onDisk;
		std::error_code       ec;
		const auto            dir = PresetIconsDir();
		std::filesystem::create_directories(dir, ec);
		for (std::filesystem::directory_iterator it(dir, ec), end; !ec && it != end; it.increment(ec)) {
			if (!it->is_regular_file(ec))
				continue;
			auto ext = PathU8(it->path().extension());
			for (auto& c : ext)
				c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
			if (ext == ".png" || ext == ".jpg" || ext == ".jpeg" || ext == ".webp") {
				icons.push_back(PathU8(it->path().filename()));
				onDisk.insert(PathU8(it->path().filename()));
			}
		}
		out["icons"] = icons;
		// Re-adopt renders whose mapping was lost BEFORE reading the map, so
		// the tab, the "Render missing" count and the batch all see the healed
		// picture in the same breath. Free ride on the scan just done.
		PresetAdoptOrphanRenders(PresetCatalogueNames(presets), onDisk);
		out["assign"] = PresetAssignments();
		// Why a preset has no image, and what the shape pass guessed about it.
		// A failure the player cannot see is a failure he retries forever.
		{
			std::lock_guard lock(g_presetAssignLock);
			json            fails = json::object();
			for (const auto& [preset, why] : g_presetFails)
				fails[preset] = why;
			out["fails"] = fails;
			json shape = json::object();
			for (const auto& [preset, s] : g_presetShape)
				shape[preset] = s;
			out["shape"] = shape;
		}
		out["races"] = PresetPlayableRaces();
		// Live batch state, so a reopened deck shows "Rendering k/N" + Stop
		// instead of a dead ✨ button while the worker runs — and "Stopping…"
		// the moment cancel lands (the flag only takes effect between renders).
		out["autorender"] = { { "running", g_presetAutoBusy.load() },
			{ "cancelling", g_presetAutoBusy.load() && g_presetAutoCancel.load() },
			{ "done", g_presetAutoDone.load() },
			{ "failed", g_presetAutoFailed.load() },
			{ "total", g_presetAutoTotal.load() },
			{ "avgMs", g_presetAvgMs.load() } };
		const json meta = PresetMeta();
		out["fav"] = meta["fav"];
		out["cats"] = meta["cats"];
		out["catOf"] = meta["catOf"];
		out["hidden"] = meta["hidden"];
		return out.dump(-1, ' ', false, nlohmann::json::error_handler_t::replace);
	}

	// ---- Faces auto-render: batch preset thumbnails via PD /thumb ----
	// One worker at a time; assign.json writes are shared with op "img", so
	// both go through g_presetAssignLock (state atomics declared up beside
	// PresetIconsDir — PresetIndexJson reports them). PresetAutoStem and
	// g_presetBurnedNames moved up beside that state: the self-heal needs both.

	// Pick the auto file for a preset: an existing non-burned candidate means
	// "already rendered, just associate"; otherwise the first free name.
	struct AutoFilePick
	{
		std::string file;
		bool        existing = false;
	};
	AutoFilePick PresetAutoFilePick(const std::string& preset)
	{
		const std::string stem = PresetAutoStem(preset);
		std::string       firstFree;
		for (int v = 1; v <= 99; ++v) {
			const std::string cand = (v == 1) ? stem + ".png" : stem + ".r" + std::to_string(v) + ".png";
			{
				std::lock_guard lock(g_presetAssignLock);
				if (g_presetBurnedNames.contains(cand))
					continue;
			}
			std::error_code ec;
			const auto      abs = PresetIconsDir() / cand;
			if (std::filesystem::exists(abs, ec) && std::filesystem::file_size(abs, ec) > 0)
				return { cand, true };
			if (firstFree.empty())
				firstFree = cand;
		}
		return { firstFree.empty() ? stem + ".png" : firstFree, false };
	}

	// Burn EVERY auto file this preset already has, so the next pick lands on a
	// fresh name and the shape pass's "already rendered, just associate"
	// short-circuit can't hand back the very render we are replacing. Used by
	// the redo and by op "render-one"; the old files are left on disk on
	// purpose (see the redo note — the delete cannot succeed this session).
	void PresetBurnExistingFiles(const std::string& preset)
	{
		const std::string stem = PresetAutoStem(preset);
		std::lock_guard   lock(g_presetAssignLock);
		for (int v = 1; v <= 99; ++v) {
			const std::string cand = (v == 1) ? stem + ".png" : stem + ".r" + std::to_string(v) + ".png";
			std::error_code   ec;
			if (std::filesystem::exists(PresetIconsDir() / cand, ec))
				g_presetBurnedNames.insert(cand);
		}
	}

	void PresetAssignIcon(const std::string& preset, const std::string& icon)
	{
		std::lock_guard lock(g_presetAssignLock);
		json            m = PresetAssignmentsUnlocked();
		if (icon.empty()) {
			m.erase(preset);
			// A hand-clear is a decision, not damage — the self-heal must not
			// hand the file straight back on the next repaint.
			g_presetNoAdopt.insert(preset);
		} else {
			m[preset] = icon;
			g_presetNoAdopt.erase(preset);
			// It has a picture now, so whatever went wrong before is history.
			g_presetFails.erase(preset);
			g_presetRedoSet.erase(preset);
		}
		WritePresetAssignmentsUnlocked(m);
	}

	// Record why a preset produced no image (shape pass reason, or PD's /thumb
	// error verbatim). The view reads these back as index.fails.
	void PresetNoteFailure(const std::string& preset, const std::string& why)
	{
		std::lock_guard lock(g_presetAssignLock);
		g_presetFails[preset] = why;
	}

	void PresetAutoRenderWorker()
	{
		const auto notify = [](std::string msg) {
			if (auto* t = SKSE::GetTaskInterface())
				t->AddTask([msg = std::move(msg)]() { RE::DebugNotification(msg.c_str()); });
		};

		// Sleep between game-touching calls, in slices, so Stop lands within
		// ~50 ms instead of after a whole breather (Bug 4, 2026-08-16).
		const auto breathe = [](int ms) {
			for (int left = ms; left > 0 && !g_presetAutoCancel.load(); left -= 50)
				std::this_thread::sleep_for(std::chrono::milliseconds(left < 50 ? left : 50));
		};

		// Every preset PD can see, minus our own face backups and anything
		// already wearing an image — plus anything the redo queued for a
		// FORCED re-render (it has an image, and that image is the problem).
		std::vector<std::string> missing;
		{
			json presets = json::parse(PresetBridge::Call("GET", "/presets", ""), nullptr, false);
			const std::vector<std::string> names = PresetCatalogueNames(presets);
			std::set<std::string>          redo;
			{
				std::lock_guard lock(g_presetAssignLock);
				redo = g_presetRedoSet;
			}
			const json assign = PresetAssignments();  // locks internally
			// A preset the player HID is not missing an image — it is out of the
			// tab on purpose, so rendering it would burn a mannequin, a spawn and
			// ~3 s for a tile nobody will see. This is also how the race-unknown
			// failures stop re-failing on every batch: hide them once.
			std::set<std::string> hidden;
			for (const auto& h : PresetMeta().value("hidden", json::array()))
				if (h.is_string())
					hidden.insert(h.get<std::string>());
			for (const auto& n : names)
				if (n.rfind("PD_", 0) != 0 && (!assign.contains(n) || redo.count(n)) && !hidden.count(n))
					missing.push_back(n);
		}
		if (missing.empty()) {
			notify("Every preset already has an image.");
			{
				std::lock_guard lock(g_presetAssignLock);
				g_presetRedoSet.clear();
			}
			g_presetAutoBusy.store(false);
			return;
		}
		logger::info("preset autorender: {} preset face(s) to render", missing.size());
		g_presetAutoTotal.store(static_cast<int>(missing.size()));
		g_presetAutoDone.store(0);
		g_presetAutoFailed.store(0);

		// A reopened deck repaints as each face lands (harmless when closed).
		// The index JSON is built HERE, off the game thread — building it in
		// the task did two directory scans on the game thread per landed face,
		// a real hitch source in the first play-test.
		const auto pushIndex = []() {
			const std::string idx = PresetIndexJson();
			if (auto* t = SKSE::GetTaskInterface())
				t->AddTask([idx]() { PushToView("fdPresetData", idx); });
		};

		// Shape phase: ask PD each preset's (race, sex) WITHOUT touching the
		// world, drop the ones whose race can't be told (cross-race applies
		// render "mannequin faces" — first play-test), and SORT by shape so
		// one stand-in serves whole runs instead of the alphabetical batch
		// thrashing spawn/despawn on every race change.
		struct Job
		{
			std::string preset, race, sex;
		};
		std::vector<Job> jobs;
		std::size_t      done = 0, failed = 0;
		for (const auto& preset : missing) {
			if (g_presetAutoCancel.load())
				break;
			// Already rendered by a previous (cancelled/crashed) run?
			if (const auto pick = PresetAutoFilePick(preset); pick.existing) {
				PresetAssignIcon(preset, pick.file);
				g_presetAutoDone.store(static_cast<int>(++done));
				continue;
			}
			json body;
			body["preset"] = preset;
			const std::string res = PresetBridge::Call("POST", "/shape",
				body.dump(-1, ' ', false, json::error_handler_t::replace));
			json r = json::parse(res, nullptr, false);
			// Every /shape is a game-thread hop; 120 of them back to back is
			// its own stutter even before a single face is drawn.
			breathe(kPresetShapeBreatherMs);
			if (r.is_discarded() || !r.value("ok", false)) {
				g_presetAutoFailed.store(static_cast<int>(++failed));
				const std::string why = r.is_discarded() ? res : r.value("error", res);
				PresetNoteFailure(preset, "Preset Director could not read this preset: " + why);
				logger::warn("preset autorender: '{}' unreadable: {}", preset, why);
				continue;
			}
			// Keep the guess EVEN WHEN it isn't confident — it is what lets the
			// tab offer "render as <race>" instead of a dead end (Bug 3).
			{
				std::lock_guard lock(g_presetAssignLock);
				g_presetShape[preset] = json{ { "race", r.value("race", "") },
					{ "sex", r.value("sex", "") },
					{ "faceEdid", r.value("faceEdid", "") },
					{ "confident", r.value("confident", false) } };
			}
			if (!r.value("confident", false)) {
				g_presetAutoFailed.store(static_cast<int>(++failed));
				const std::string face = r.value("faceEdid", "");
				PresetNoteFailure(preset,
					"Can't tell which race this preset is for" +
						(face.empty() ? std::string(" (its head part didn't resolve)") :
										std::string(" (face part: ") + face + ")") +
						" — pick a race and re-render just this one.");
				logger::warn("preset autorender: '{}' skipped — can't tell its race (face part: {})",
					preset, face.empty() ? "unresolved" : face);
				continue;
			}
			jobs.push_back({ preset, r.value("race", ""), r.value("sex", "") });
		}
		std::stable_sort(jobs.begin(), jobs.end(), [](const Job& a, const Job& b) {
			return std::tie(a.race, a.sex, a.preset) < std::tie(b.race, b.sex, b.preset);
		});
		if (failed)
			logger::info("preset autorender: {} preset(s) skipped in the shape pass", failed);
		pushIndex();

		if (!jobs.empty())
			notify("Rendering " + std::to_string(jobs.size()) +
				   " preset faces — a lone stand-in will appear beside you while this runs.");

		// Fail-fast: a broken PRECONDITION (MRF not installed, PD leash dead)
		// fails every preset the same way — grinding the whole library through
		// it would waste minutes. Distinct per-preset errors keep going.
		std::string sameErr;
		int         sameErrRun = 0;
		std::size_t lastDone = done;  // did THIS pass land a face? (feeds avgMs)

		for (const auto& job : jobs) {
			if (g_presetAutoCancel.load()) {
				logger::info("preset autorender: cancelled at {}/{}", done, missing.size());
				break;
			}
			const auto started = std::chrono::steady_clock::now();
			const auto pick = PresetAutoFilePick(job.preset);
			json       body;
			body["preset"] = job.preset;
			body["out"] = PathU8((PresetIconsDir() / pick.file));
			body["px"] = 1024;
			body["flags"] = 3;
			const std::string res = PresetBridge::Call("POST", "/thumb",
				body.dump(-1, ' ', false, json::error_handler_t::replace));
			json r = json::parse(res, nullptr, false);
			if (!r.is_discarded() && r.value("ok", false) && r.value("saved", false)) {
				PresetAssignIcon(job.preset, pick.file);  // clears any earlier fail
				g_presetAutoDone.store(static_cast<int>(++done));
				sameErrRun = 0;
				pushIndex();
			} else {
				const std::string err = r.is_discarded() ? res : r.value("error", res);
				g_presetAutoFailed.store(static_cast<int>(++failed));
				PresetNoteFailure(job.preset, err);
				logger::warn("preset autorender: '{}' failed: {}", job.preset, err);
				sameErrRun = (err == sameErr) ? sameErrRun + 1 : 1;
				sameErr = err;
				if (sameErrRun >= 3 && done == 0) {
					notify("Preset rendering stopped — every attempt fails the same way: " + err);
					logger::error("preset autorender: aborted, repeated error: {}", err);
					break;
				}
			}
			if ((done + failed) % 5 == 0)
				notify("Preset faces: " + std::to_string(done + failed) + "/" +
					   std::to_string(missing.size()) + "…");
			// Give the game a beat. A /thumb spawns a stand-in, runs Papyrus and
			// renders in the LIVE world; 114 of them nose-to-tail is the "pretty
			// bad lag" Rober reported on 2026-08-16. Sliced, so Stop still bites.
			breathe(kPresetRenderBreatherMs);
			// Measured AFTER the breather: the estimate should describe the wait,
			// not the render. Only when the face actually landed (see g_presetAvgMs).
			if (done > lastDone) {
				lastDone = done;
				const auto ms = static_cast<int>(std::chrono::duration_cast<std::chrono::milliseconds>(
					std::chrono::steady_clock::now() - started)
														 .count());
				const int prev = g_presetAvgMs.load();
				g_presetAvgMs.store(prev > 0 ? (prev * 2 + ms) / 3 : ms);
			}
		}

		PresetBridge::Call("POST", "/thumb-cleanup", "{}");
		// A forced re-render is spent whether it finished or was stopped — a
		// preset left in the set would keep showing up under "Render missing"
		// while wearing a perfectly good picture. Press ↻ again to resume.
		{
			std::lock_guard lock(g_presetAssignLock);
			g_presetRedoSet.clear();
		}
		const bool cancelled = g_presetAutoCancel.load();
		logger::info("preset autorender: {} rendered, {} failed{}", done, failed,
			cancelled ? " (cancelled)" : "");
		notify(cancelled ?
				("Preset rendering stopped — " + std::to_string(done) + " done.") :
				("Rendered " + std::to_string(done) + " preset faces" +
					(failed ? " (" + std::to_string(failed) + " failed — see the log)" : "") +
					" — open the Faces tab."));
		g_presetAutoBusy.store(false);
		pushIndex();  // after busy clears, so the view's Stop chip retires
	}

	// ---- One preset, on demand (op "render-one") ----
	// Rober, 2026-08-16: one bad face used to mean re-running the whole
	// library. This ALWAYS renders — never the batch's "already has an image,
	// just associate" short-circuit — because the whole point is that the
	// image it has is wrong. `race`/`sex`, when given, override PD's shape
	// inference: that is how the six presets whose head part never resolved
	// ('Preset_6-6-2017_12-51-4', drae1..drae5) become renderable at all.
	// A failure comes back as fdPresetResult AND lands in index.fails — a
	// button that does nothing and says nothing is the bug we are fixing.
	// `keepStandIn` (2026-08-16, Rober's in-game face experiment): ask PD to PIN
	// the stand-in it spawned so a later batch's cleanup cannot delete it, and
	// skip our own /thumb-cleanup — she is left standing next to the player to
	// be looked at. Default false, so the everyday path is byte-identical.
	void PresetRenderOneWorker(std::string preset, std::string race, std::string sex, bool keepStandIn)
	{
		const auto notify = [](std::string msg) {
			if (auto* t = SKSE::GetTaskInterface())
				t->AddTask([msg = std::move(msg)]() { RE::DebugNotification(msg.c_str()); });
		};
		const auto reply = [](const json& r) {
			const std::string s = r.dump(-1, ' ', false, json::error_handler_t::replace);
			if (auto* t = SKSE::GetTaskInterface())
				t->AddTask([s]() { PushToView("fdPresetResult", s); });
		};

		// Burn what it has now: Ultralight caches by filename for the whole
		// session, so re-rendering over the same name would repaint the very
		// bytes we are replacing. The old file stays on disk — it cannot be
		// deleted while Ultralight holds it mapped, and the self-heal prefers
		// the NEWEST render, so a leftover is harmless.
		PresetBurnExistingFiles(preset);
		const auto pick = PresetAutoFilePick(preset);

		json body;
		body["preset"] = preset;
		body["out"] = PathU8((PresetIconsDir() / pick.file));
		body["px"] = 1024;
		body["flags"] = 3;
		if (!race.empty())
			body["race"] = race;
		if (!sex.empty())
			body["sex"] = sex;
		if (keepStandIn)
			body["keepStandIn"] = true;
		const std::string res = PresetBridge::Call("POST", "/thumb",
			body.dump(-1, ' ', false, json::error_handler_t::replace));
		json r = json::parse(res, nullptr, false);

		// PD answers these two only when it pinned something; absent = the
		// ordinary render, and the view simply never sees the keys.
		const std::string standIn = (!r.is_discarded() && r.is_object()) ? r.value("standIn", std::string()) : std::string();
		const bool        kept    = (!r.is_discarded() && r.is_object()) && r.value("kept", false);

		bool        ok = false;
		std::string err;
		if (!r.is_discarded() && r.value("ok", false) && r.value("saved", false)) {
			ok = true;
			PresetAssignIcon(preset, pick.file);  // clears any earlier fail
			g_presetAutoDone.store(1);
			logger::info("preset render-one: '{}' rendered as {}{}", preset, pick.file,
				race.empty() ? "" : (" (forced race " + race + "/" + (sex.empty() ? "male" : sex) + ")"));
		} else {
			err = r.is_discarded() ? res : r.value("error", res);
			g_presetAutoFailed.store(1);
			PresetNoteFailure(preset, err);
			logger::warn("preset render-one: '{}' failed: {}", preset, err);
		}

		// The pinned stand-in is the POINT when keepStandIn is set — cleaning up
		// here would delete the very thing the player asked to look at. Op
		// "standin-clear" is how she goes away.
		if (!keepStandIn)
			PresetBridge::Call("POST", "/thumb-cleanup", "{}");
		if (kept)
			logger::info("preset stand-in: kept {} next to the player (render-one '{}')",
				standIn.empty() ? "the stand-in" : standIn, preset);
		notify(ok ? (kept ? ("Rendered " + preset + " — she is standing next to you.") :
							("Rendered " + preset + " — open the Faces tab.")) :
					("Couldn't render " + preset + ": " + err));
		g_presetAutoBusy.store(false);
		// op rides along so the view matches this reply EXACTLY rather than
		// inferring it from the preset name — fdPresetResult is a shared channel.
		reply(json{ { "op", "render-one" },
			{ "ok", ok },
			{ "preset", preset },
			{ "icon", ok ? pick.file : "" },
			{ "standIn", standIn },
			{ "kept", kept },
			{ "error", err } });
		// Built off the game thread, pushed as a task — same law as the batch.
		const std::string idx = PresetIndexJson();
		if (auto* t = SKSE::GetTaskInterface())
			t->AddTask([idx]() { PushToView("fdPresetData", idx); });
	}

	// ---- The face experiment (ops "render-probe" / "standin-clear") ----
	// Rober, 2026-08-16: look at the preset IN GAME instead of judging it from a
	// 1024px tile. Deliberately a SIBLING of render-one rather than more flags on
	// it, for three reasons worth keeping:
	//   1. PD's `headOnly` is an A/B knob that must NEVER become the everyday
	//      default. A separate op makes that structural instead of a promise
	//      about flag discipline.
	//   2. A probe NEVER assigns, never notes a failure and never burns the
	//      preset's filenames — so a failed experiment cannot blank a good tile
	//      or plant an entry in index.fails.
	//   3. Its output goes to its OWN filename, so it cannot overwrite the real
	//      tile even by accident (the coordinator's explicit requirement).
	// render-one keeps its exact previous contract; only the optional
	// keepStandIn passthrough was added there.

	// A fresh name per probe. Ultralight memory-maps every image it has drawn and
	// holds it for the session, so reusing one filename would repaint the FIRST
	// probe's bytes forever — the counter is what makes A/B actually visible.
	// "probe-" can never collide with the "auto-<preset>[.rN]" naming law that
	// PresetAutoFilesOnDisk / the self-heal scan, so a probe is invisible to
	// every path that adopts renders.
	std::string PresetProbeFileName(const std::string& preset)
	{
		static std::atomic<int> s_seq{ 0 };
		// PresetAutoStem sanitises the preset name and always starts "auto-".
		const std::string stem = PresetAutoStem(preset).substr(5);
		return "probe-" + stem + "-" + std::to_string(s_seq.fetch_add(1) + 1) + ".png";
	}

	void PresetRenderProbeWorker(std::string preset, std::string race, std::string sex,
		bool headOnly, bool keepStandIn)
	{
		const auto notify = [](std::string msg) {
			if (auto* t = SKSE::GetTaskInterface())
				t->AddTask([msg = std::move(msg)]() { RE::DebugNotification(msg.c_str()); });
		};
		const auto reply = [](const json& r) {
			const std::string s = r.dump(-1, ' ', false, json::error_handler_t::replace);
			if (auto* t = SKSE::GetTaskInterface())
				t->AddTask([s]() { PushToView("fdPresetResult", s); });
		};

		const std::string file = PresetProbeFileName(preset);

		json body;
		body["preset"] = preset;
		body["out"] = PathU8((PresetIconsDir() / file));
		body["px"] = 1024;
		body["flags"] = 3;
		if (!race.empty())
			body["race"] = race;
		if (!sex.empty())
			body["sex"] = sex;
		if (headOnly)
			body["headOnly"] = true;
		if (keepStandIn)
			body["keepStandIn"] = true;
		const std::string res = PresetBridge::Call("POST", "/thumb",
			body.dump(-1, ' ', false, json::error_handler_t::replace));
		const json r = json::parse(res, nullptr, false);

		const bool        obj  = !r.is_discarded() && r.is_object();
		const bool        ok   = obj && r.value("ok", false) && r.value("saved", false);
		const std::string standIn = obj ? r.value("standIn", std::string()) : std::string();
		const bool        kept = obj && r.value("kept", false);
		const std::string err  = ok ? std::string() : (obj ? r.value("error", res) : res);

		if (ok)
			// Build marker (hd-markers.json: "preset probe:").
			logger::info("preset probe: '{}' rendered as {} (headOnly={}, standIn={}, kept={})",
				preset, file, headOnly ? "yes" : "no",
				standIn.empty() ? "-" : standIn, kept ? "yes" : "no");
		else
			logger::warn("preset probe: '{}' failed: {}", preset, err);

		if (!keepStandIn)
			PresetBridge::Call("POST", "/thumb-cleanup", "{}");

		// std::string on every branch: a bare literal here would make the outer
		// ternary mix const char* with std::string and fail to compile.
		notify(ok ? (kept ? std::string("Probe rendered — she is standing next to you.") :
							std::string("Probe rendered — check the Faces tab.")) :
					("Probe failed: " + err));
		g_presetAutoBusy.store(false);
		// NO PresetAssignIcon / PresetNoteFailure / PresetBurnExistingFiles here,
		// and no fdPresetData push: a probe changes nothing the tab draws.
		reply(json{ { "op", "render-probe" },
			{ "ok", ok },
			{ "preset", preset },
			{ "file", ok ? file : "" },
			{ "headOnly", headOnly },
			{ "standIn", standIn },
			{ "kept", kept },
			{ "error", err } });
	}

	// Send a pinned stand-in away. Worker thread, because PresetBridge::Call
	// blocks on a game-thread round trip.
	void PresetStandInClearWorker()
	{
		const std::string res = PresetBridge::Call("POST", "/thumb-cleanup", R"({"force":true})");
		const json        r = json::parse(res, nullptr, false);
		const bool        obj = !r.is_discarded() && r.is_object();
		const std::string err = obj ? r.value("error", std::string()) : res;
		// `ok` DEFAULTS TRUE on a well-formed object with no error: render-one has
		// always fired /thumb-cleanup and thrown the reply away, so this route's
		// success shape is unverified from here. An explicit ok:false or an error
		// string is still believed — a forgiving default must not make a real
		// refusal read as success.
		const bool        ok = obj && r.value("ok", true) && err.empty();
		// PD reports `kept` as "is one STILL pinned" — true here would mean the
		// force did not take, so it is reported rather than assumed away.
		const bool        kept = obj && r.value("kept", false);

		// Build marker (hd-markers.json: "preset stand-in: cleared").
		if (ok)
			logger::info("preset stand-in: cleared (still pinned: {})", kept ? "yes" : "no");
		else
			logger::warn("preset stand-in: clear failed: {}", err.empty() ? res : err);

		if (auto* t = SKSE::GetTaskInterface())
			t->AddTask([ok, kept, err]() {
				const std::string msg = ok ? std::string("Stand-in sent away.") :
											 ("Couldn't send the stand-in away: " + err);
				RE::DebugNotification(msg.c_str());
				PushToView("fdPresetResult",
					json{ { "op", "standin-clear" }, { "ok", ok }, { "kept", kept }, { "error", err } }
						.dump(-1, ' ', false, json::error_handler_t::replace));
			});
	}

	void OnJsFolPreset(const char* data)
	{
		if (!data)
			return;
		const auto j = json::parse(data, nullptr, false);
		if (j.is_discarded() || !j.is_object()) {
			logger::warn("fdPreset: bad payload");
			return;
		}
		const std::string op = j.value("op", "");

		if (op == "index") {
			logger::info("PresetDeck: index requested");
			const std::string idx = PresetIndexJson();
			PushToView("fdPresetData", idx);
			// Mirror the catalogue to disk so the Deck Portal can browse presets
			// with the game closed — the .jslot files are scattered across mod
			// folders and only PD's VFS view sees them all. faces-preset-deck-catalogue.
			std::error_code ec;
			std::ofstream   cat(DeckViewDir() / "faces-catalogue.json", std::ios::trunc);
			if (cat)
				cat << idx;
			return;
		}

		if (op == "img") {
			// Assign (or clear) an icon file for a preset name — deck-side
			// file IO only, PD never hears about images. Shares the assign
			// lock with the auto-render worker.
			const std::string preset = j.value("preset", "");
			const std::string icon = j.value("icon", "");
			if (preset.empty())
				return;
			PresetAssignIcon(preset, icon);
			PushToView("fdPresetData", PresetIndexJson());
			return;
		}

		if (op == "autorender") {
			// Render a thumbnail for every preset with no image, via PD's
			// /thumb (mannequin + MRF). Papyrus must run (LoadCharacterEx),
			// so the palette closes — same law as the party orders.
			if (!PresetBridge::Available()) {
				PushToView("fdPresetResult",
					R"({"ok":false,"error":"Preset Director isn't loaded — the auto-render needs it"})");
				return;
			}
			if (g_presetAutoBusy.exchange(true)) {
				PushToView("fdPresetResult", R"({"ok":false,"error":"a render batch is already running"})");
				return;
			}
			g_presetAutoCancel.store(false);
			ClosePalette();
			std::thread(PresetAutoRenderWorker).detach();
			return;
		}
		if (op == "autorender-cancel") {
			g_presetAutoCancel.store(true);
			// Immediate feedback: the flag only lands between renders (each
			// takes seconds) — push the index NOW so the chip flips to
			// "Stopping…" instead of looking dead (first play-test report).
			PushToView("fdPresetData", PresetIndexJson());
			return;
		}

		if (op == "render-one") {
			// One preset, always re-rendered, optionally forced to a race/sex.
			// {op:"render-one", preset, race?, sex?, keepStandIn?} → fdPresetResult
			//   {ok, preset, icon, standIn, kept, error} + a fresh fdPresetData.
			// keepStandIn leaves her in the world afterwards (op "standin-clear"
			// sends her away); omitted, this path is exactly what it always was.
			const std::string preset = j.value("preset", "");
			const std::string race = j.value("race", "");
			const std::string sex = j.value("sex", "");
			const bool        keepStandIn = j.value("keepStandIn", false);
			// Every refusal echoes op + preset too, so the view clears the right
			// pending tile instead of waiting out its 120 s backstop.
			const auto refuse = [&](const std::string& why) {
				PushToView("fdPresetResult",
					json{ { "op", "render-one" }, { "ok", false }, { "preset", preset }, { "error", why } }
						.dump(-1, ' ', false, json::error_handler_t::replace));
			};
			if (preset.empty()) {
				refuse("which preset?");
				return;
			}
			if (!PresetBridge::Available()) {
				refuse("Preset Director isn't loaded — rendering needs it");
				return;
			}
			// Firing this mid-batch is a normal thing to try; say so plainly
			// rather than queueing a second stand-in into the same world.
			if (g_presetAutoBusy.exchange(true)) {
				refuse("a render is already running — stop it first");
				return;
			}
			g_presetAutoCancel.store(false);
			g_presetAutoTotal.store(1);
			g_presetAutoDone.store(0);
			g_presetAutoFailed.store(0);
			logger::info("preset render-one: '{}' requested{}", preset,
				race.empty() ? "" : (" as " + race));
			// Same law as the batch: /thumb applies the preset through Papyrus,
			// and Papyrus does not run while the palette has the game paused.
			ClosePalette();
			std::thread(PresetRenderOneWorker, preset, race, sex, keepStandIn).detach();
			return;
		}

		if (op == "render-probe") {
			// The in-game face experiment. {op:"render-probe", preset, race?, sex?,
			// headOnly?, keepStandIn?} → fdPresetResult {op, ok, preset, file,
			// headOnly, standIn, kept, error}. NO fdPresetData follows — a probe
			// changes nothing the tab draws.
			//
			// keepStandIn DEFAULTS TRUE here (unlike render-one): standing next to
			// her is the entire purpose of the op. headOnly defaults FALSE and is
			// an explicit A/B opt-in — it must never become the everyday path.
			const std::string preset = j.value("preset", "");
			const std::string race = j.value("race", "");
			const std::string sex = j.value("sex", "");
			const bool        headOnly = j.value("headOnly", false);
			const bool        keepStandIn = j.value("keepStandIn", true);
			const auto        refuse = [&](const std::string& why) {
				PushToView("fdPresetResult",
					json{ { "op", "render-probe" }, { "ok", false }, { "preset", preset },
						{ "headOnly", headOnly }, { "error", why } }
						.dump(-1, ' ', false, json::error_handler_t::replace));
			};
			if (preset.empty()) {
				refuse("which preset?");
				return;
			}
			if (!PresetBridge::Available()) {
				refuse("Preset Director isn't loaded — the probe needs it");
				return;
			}
			if (g_presetAutoBusy.exchange(true)) {
				refuse("a render is already running — stop it first");
				return;
			}
			g_presetAutoCancel.store(false);
			// Deliberately NOT touching total/done/failed: those drive the tab's
			// "Rendering k/N" chip, and a probe is not part of any batch.
			// Build marker (hd-markers.json: "preset probe: '").
			logger::info("preset probe: '{}' requested (headOnly={}, keepStandIn={}){}",
				preset, headOnly ? "yes" : "no", keepStandIn ? "yes" : "no",
				race.empty() ? "" : (" as " + race));
			// Same law as render-one: /thumb applies the preset through Papyrus,
			// which does not run while the palette has the game paused.
			ClosePalette();
			std::thread(PresetRenderProbeWorker, preset, race, sex, headOnly, keepStandIn).detach();
			return;
		}

		if (op == "standin-clear") {
			// {op:"standin-clear"} → fdPresetResult {op, ok, kept, error}.
			// Refused mid-render on purpose: a FORCED cleanup would delete the
			// stand-in the running batch is using.
			const auto refuse = [&](const std::string& why) {
				PushToView("fdPresetResult",
					json{ { "op", "standin-clear" }, { "ok", false }, { "error", why } }
						.dump(-1, ' ', false, json::error_handler_t::replace));
			};
			if (!PresetBridge::Available()) {
				refuse("Preset Director isn't loaded");
				return;
			}
			if (g_presetAutoBusy.load()) {
				refuse("a render is running — it is using the stand-in; stop it first");
				return;
			}
			// Palette closed first for the same reason render-one does it: the PD
			// call blocks on a game-thread round trip, and a paused world is how
			// that turns into a wedged worker rather than a slow one.
			ClosePalette();
			std::thread(PresetStandInClearWorker).detach();
			return;
		}

		if (op == "autorender-redo") {
			// Re-render EVERY auto thumbnail (an early batch left glitched
			// ones).
			//
			// ⚠ THE 2026-08-16 TRAP — do not reintroduce it. This used to
			// ERASE every auto- assignment and delete its file BEFORE
			// rendering anything. Two things then went wrong at once: the
			// delete silently failed (Ultralight memory-maps every image it
			// has drawn and holds it for the session, so remove() returns a
			// sharing violation into an ignored error_code), and a batch that
			// was cancelled — or crashed, or was walked away from — never
			// rebuilt the map it had just thrown away. Measured that day:
			// 234 auto-*.png on disk, TEN entries in assign.json, the human's
			// whole library blank. 109 + 114 + 1 + 10 = 234, i.e. every render
			// ever made was still there and nothing claimed it.
			//
			// So the redo destroys NOTHING up front. It only (a) burns the
			// filenames so the next pick is fresh, and (b) queues the presets
			// for a forced re-render. Each assignment is replaced the moment
			// its new render lands, so a cancel costs exactly the faces not
			// yet redone — never the ones already good.
			if (!PresetBridge::Available()) {
				PushToView("fdPresetResult",
					R"({"ok":false,"error":"Preset Director isn't loaded — the auto-render needs it"})");
				return;
			}
			if (g_presetAutoBusy.exchange(true)) {
				PushToView("fdPresetResult", R"({"ok":false,"error":"a render batch is already running"})");
				return;
			}
			std::size_t queued = 0;
			{
				std::lock_guard lock(g_presetAssignLock);
				const json      m = PresetAssignmentsUnlocked();
				for (const auto& [preset, icon] : m.items()) {
					const std::string file = icon.is_string() ? icon.get<std::string>() : "";
					if (file.rfind("auto-", 0) != 0)
						continue;  // a hand-picked image is the player's, never ours to redo
					g_presetRedoSet.insert(preset);
					++queued;
				}
			}
			// Burn outside the map walk (PresetBurnExistingFiles takes the same
			// lock): every generation on disk, so the shape pass's "already
			// rendered" short-circuit can't hand back the render we are redoing.
			{
				std::set<std::string> queuedNames;
				{
					std::lock_guard lock(g_presetAssignLock);
					queuedNames = g_presetRedoSet;
				}
				for (const auto& preset : queuedNames)
					PresetBurnExistingFiles(preset);
			}
			logger::info("preset autorender: redo — {} preset(s) queued, assignments kept until each one lands",
				queued);
			g_presetAutoCancel.store(false);
			ClosePalette();
			std::thread(PresetAutoRenderWorker).detach();
			return;
		}

		// ---- Faces favorites + categories (faces-meta) ----
		if (op == "fav") {
			const std::string preset = j.value("preset", "");
			const bool        on = j.value("on", true);
			if (preset.empty())
				return;
			json m = PresetMeta();
			json arr = json::array();
			bool present = false;
			for (auto& e : m["fav"]) {
				if (e.is_string() && e.get<std::string>() == preset) { present = true; continue; }  // drop dups / the one we toggle off
				arr.push_back(e);
			}
			if (on && !present)
				arr.push_back(preset);
			m["fav"] = arr;
			WritePresetMeta(m);
			PushToView("fdPresetData", PresetIndexJson());
			return;
		}
		if (op == "hide") {
			// Remove one preset from the tab (on=true) or bring it back. Same
			// shape as "fav": a name list in meta.json, never a file operation.
			const std::string preset = j.value("preset", "");
			const bool        on = j.value("on", true);
			if (preset.empty())
				return;
			json m = PresetMeta();
			json arr = json::array();
			bool present = false;
			for (auto& e : m["hidden"]) {
				if (e.is_string() && e.get<std::string>() == preset) { present = true; continue; }
				arr.push_back(e);
			}
			if (on && !present)
				arr.push_back(preset);
			m["hidden"] = arr;
			WritePresetMeta(m);
			logger::info("faces: preset '{}' {}", preset, on ? "hidden" : "restored");
			PushToView("fdPresetData", PresetIndexJson());
			return;
		}
		if (op == "cat-new" || op == "cat-del" || op == "cat-rename") {
			json m = PresetMeta();
			if (op == "cat-new") {
				const std::string name = j.value("name", "");
				bool have = false;
				for (auto& c : m["cats"]) if (c.is_string() && c.get<std::string>() == name) have = true;
				if (!name.empty() && !have)
					m["cats"].push_back(name);
			} else if (op == "cat-del") {
				const std::string name = j.value("name", "");
				json keep = json::array();
				for (auto& c : m["cats"]) if (!(c.is_string() && c.get<std::string>() == name)) keep.push_back(c);
				m["cats"] = keep;
				// unfile every preset that pointed at it
				json catOf = json::object();
				for (auto& [k, v] : m["catOf"].items())
					if (!(v.is_string() && v.get<std::string>() == name)) catOf[k] = v;
				m["catOf"] = catOf;
			} else {  // cat-rename
				const std::string from = j.value("from", ""), to = j.value("to", "");
				if (!from.empty() && !to.empty()) {
					json cats = json::array();
					for (auto& c : m["cats"]) cats.push_back((c.is_string() && c.get<std::string>() == from) ? json(to) : c);
					m["cats"] = cats;
					for (auto& [k, v] : m["catOf"].items())
						if (v.is_string() && v.get<std::string>() == from) m["catOf"][k] = to;
				}
			}
			WritePresetMeta(m);
			PushToView("fdPresetData", PresetIndexJson());
			return;
		}
		if (op == "cat-set") {
			const std::string preset = j.value("preset", "");
			const std::string cat = j.value("cat", "");
			if (preset.empty())
				return;
			json m = PresetMeta();
			if (cat.empty())
				m["catOf"].erase(preset);
			else
				m["catOf"][preset] = cat;
			WritePresetMeta(m);
			PushToView("fdPresetData", PresetIndexJson());
			return;
		}

		if (op == "saveplayer") {
			// Back the player's current face up (Faces tab "try on me" revert).
			const std::string name = j.value("name", "PD_MyFaceBackup");
			std::thread([name]() {
				json body;
				body["name"] = name;
				const std::string res = PresetBridge::Call("POST", "/save-player", body.dump(-1, ' ', false, nlohmann::json::error_handler_t::replace));
				if (auto* tasks = SKSE::GetTaskInterface())
					tasks->AddTask([res]() { PushToView("fdPresetResult", res); });
			}).detach();
			return;
		}

		if (op == "apply" || op == "spawn") {
			json body;
			// Face shape + morphs only by default: flags 15's SkinOverrides
			// half painted the first live test target BLUE (textures her body
			// doesn't have). "full" is the caller's explicit opt-in.
			body["flags"] = j.value("flags", 3);
			body["preset"] = j.value("preset", "");
			std::string path;
			if (op == "apply") {
				const std::uint32_t formId = j.value("formId", 0u);
				if (!formId || body["preset"].get<std::string>().empty()) {
					PushToView("fdPresetResult", R"({"ok":false,"error":"need a person and a preset"})");
					return;
				}
				char hex[16];
				std::snprintf(hex, sizeof(hex), "%08X", formId);
				body["ref"] = hex;
				path = "/apply";
			} else {
				body["base"] = j.value("base", "2004C26");  // Traveling Pilgrim, the proven donor
				body["name"] = j.value("name", "");
				path = "/spawn";
			}
			std::thread([path, payload = body.dump(-1, ' ', false, nlohmann::json::error_handler_t::replace)]() {
				const std::string res = PresetBridge::Call("POST", path, payload);
				if (auto* tasks = SKSE::GetTaskInterface())
					tasks->AddTask([res]() { PushToView("fdPresetResult", res); });
			}).detach();
			return;
		}

		logger::warn("fdPreset: unknown op {}", op);
	}

	void OnJsFolNpc(const char* data)
	{
		if (!data)
			return;
		const auto j = json::parse(data, nullptr, false);
		if (j.is_discarded() || !j.is_object()) {
			logger::warn("fdNpc: bad payload");
			return;
		}
		const std::string cmd     = j.dump(-1, ' ', false, nlohmann::json::error_handler_t::replace);
		// Both container ops hand the focus to a menu the deck must not be
		// sitting on top of. "storage" was missed when it was added — the spare
		// inventory opened UNDER the palette, which is the overlap this project
		// treats as a bug (Rober, 2026-08-03).
		const auto        npcOp  = j.value("op", std::string(""));
		// Trade (Rober, 2026-08-17) rides this same door rather than a bridge of
		// its own: the card already sends every per-person verb through fdNpc,
		// and the reply shape fdNpcResult renders is the one TradeActions
		// answers with. Whichever menu it picks — barter or pack — needs the
		// focus, so it joins the closing set.
		const bool        trade   = TradeActions::IsAction(npcOp);
		// Recruitment/dismissal run Papyrus and must release the focus pause.
		// Keeping F7 open stranded these requests until the player closed it.
		// Attack (the card's per-person sic 'em, 2026-09-23) is a deck verb, not
		// an NFF one — NpcActions::SicEmOne. StartCombat is Papyrus, so the
		// palette closes, and like the bindable Sic 'em it stays closed: the
		// fight must not sit paused under the deck.
		const bool        attack  = (npcOp == "attack");
		std::uint32_t     attackId = 0;
		if (attack) {
			const auto s = j.value("formId", std::string(""));
			if (!s.empty()) {
				try {
					attackId = static_cast<std::uint32_t>(std::stoul(s, nullptr, 16));
				} catch (...) {}
			}
		}
		const bool        recall = (npcOp == "allSummon");
		const bool        closing = (npcOp == "inventory" || npcOp == "storage" || trade || attack || recall ||
			npcOp == "recruit" || npcOp == "dismiss" || npcOp == "unwedge");

		SKSE::GetTaskInterface()->AddTask([cmd, closing, trade, attack, attackId, recall]() {
			if (closing)
				ClosePalette();  // the container menu needs the focus back

			if (attack) {
				std::string msg;
				const bool ok = NpcActions::SicEmOne(attackId, msg);  // puts msg on screen itself
				PushToView("fdNpcResult", json{ { "ok", ok }, { "op", "attack" }, { "phase", "done" },
					{ "msg", msg } }.dump(-1, ' ', false, json::error_handler_t::replace));
				return;
			}

			if (trade) {
				// One answer, no callback: the barter dispatch is fire-and-forget
				// (trade_actions.h), and the palette is already shut, so the
				// on-screen notification is the only reply the player can read.
				const auto res = TradeActions::Apply(cmd);
				PushToView("fdNpcResult", res);
				const auto jt = json::parse(res, nullptr, false);
				if (!jt.is_discarded()) {
					const auto msg = jt.value("msg", std::string(""));
					if (!msg.empty())
						RE::DebugNotification(msg.c_str());
				}
				return;
			}

			const auto pre = NffControl::Apply(cmd, [](const std::string& res) {
				// Already on the main thread — NffControl hops for us.
				PushToView("fdNpcResult", res);
				// A recruit changes the roster's "following" state, so re-push
				// the things that render it rather than leaving a stale badge.
				const auto fo = FollowerDeck::StateJson();
				PushToView("fdState", fo);
				PushFollowerNff(fo);
				const auto jr = json::parse(res, nullptr, false);
				if (!jr.is_discarded()) {
					const auto msg = jr.value("msg", std::string(""));
					if (!msg.empty())
						RE::DebugNotification(msg.c_str());
				}
			});

			PushToView("fdNpcResult", pre);

			// A refusal never reaches the callback above, so say it here or it
			// is said nowhere — the palette may already be shut.
			const auto jp = json::parse(pre, nullptr, false);
			if (!jp.is_discarded() && (recall || !jp.value("ok", false))) {
				const auto msg = jp.value("msg", std::string(""));
				if (!msg.empty())
					RE::DebugNotification(msg.c_str());
			}
		});
	}

